window.EXPL={"감정평2016_27-81-3":{"f":"좁은 의미의 부동산과 준부동산을 합쳐 광의의 부동산이라 하며, 자본, 자산 등과 함께 경제적 측면에서의 부동산으로 구분된다.","w":"자본·자산 등은 경제적 측면의 부동산이다. 기술적(물리적) 측면의 부동산은 공간, 자연, 환경, 위치로 본다.","c":"중"},"감정평2016_27-112-5":{"f":"도시형 생활주택은 300세대 미만의 국민주택규모에 해당하는 주택으로서 단지형 연립주택, 단지형 다세대주택, 원룸형 주택으로 분류한다.","w":"단지형 연립주택·단지형 다세대주택·원룸형 주택으로 나뉘는 300세대 미만의 국민주택규모 주택은 도시형 생활주택이다. 세대구분형 공동주택은 주택 내부 공간을 세대별로 구분한 공동주택이다.","c":"상"},"감정평2017_28-95-4":{"f":"부동산은 용익물권과 담보물권의 설정이 가능하다.","w":"지상권·지역권·전세권 같은 용익물권과 저당권 같은 담보물권은 부동산에 설정한다. 동산에는 용익물권을 설정할 수 없고 질권만 설정한다.","c":"상"},"감정평2017_28-97-5":{"f":"임차인이 설치한 영업용 선반ㆍ카운터 등 사업이나 생활의 편의를 위해 설치한 정착물은 일반적으로 동산으로 취급한다.","w":"임차인이 설치한 영업용 선반·카운터 같은 가식(임시) 정착물은 임대차가 끝나면 철거하므로 토지와 별개의 동산으로 본다.","c":"상"},"감정평2018_29-83-2":{"f":"입목을 위한 법정지상권은 성립한다.","w":"입목에 관한 법률에 따라 입목이 저당권의 목적이 되어 토지와 입목의 소유자가 달라지면 입목소유자에게 법정지상권이 성립한다.","c":"상"},"감정평2018_29-85-1":{"f":"신축 중인 건물은 사용승인이 완료되기 전에도 토지와 별개의 부동산으로 취급될 수 있다.","w":"기둥·지붕·주벽을 갖춘 신축 중인 건물은 사용승인 전이라도 토지와 별개의 독립된 부동산으로 본다.","c":"중"},"감정평2018_29-85-2":{"f":"개개의 수목은 명인방법을 갖추면 토지와 별개의 부동산으로 취급된다.","w":"수목은 원래 토지의 일부이지만 명인방법을 갖추면 토지와 독립된 부동산으로 거래할 수 있다.","c":"상"},"감정평2018_29-85-3":{"f":"토지에 정착된 담장은 토지와 별개의 부동산으로 취급되지 않는다.","w":"담장은 토지의 종속 정착물이어서 토지의 일부로 취급된다.","c":"상"},"감정평2018_29-85-5":{"f":"총톤수 20톤 이상의 기선(機船)과 범선(帆船)은 등기가 가능하다.","w":"선박등기가 되는 기선·범선은 총톤수 20톤 이상이다. 10톤 이상이라는 기준은 맞지 않다.","c":"상"},"감정평2019_30-84-5":{"f":"「입목에 관한 법률」에 의해 소유권보존등기를 한 입목은 토지와 분리하여 양도할 수 있다.","w":"소유권보존등기를 한 입목은 부동산으로 보므로 토지와 분리하여 양도하거나 저당권의 목적으로 할 수 있다.","c":"상"},"감정평2020_31-112-1":{"f":"빈지는 일반적으로 바다와 육지 사이의 해변 토지와 같이 소유권이 인정되지 않지만 이용실익이 있는 토지이다.","w":"빈지는 소유권이 인정되지 않으면서 이용실익은 있는 해변 토지이다. 소유권이 인정되지만 이용실익이 없는 토지는 법지이다.","c":"상"},"감정평2020_31-113-4":{"f":"지중권 또는 지하권은 토지소유자가 지하공간으로부터 어떤 이익을 획득하거나 사용할 수 있는 권리를 말하며, 물을 이용할 수 있는 권리가 이에 포함되지 않는다.","w":"지하권에는 물을 이용하는 권리(용수권)가 들어가지 않는다. 용수권은 별개의 권리로 본다.","c":"중"},"감정평2021_32-81-5":{"f":"부동산의 법률적·경제적·물리적 측면을 결합한 개념을 복합개념의 부동산이라고 한다.","w":"법률적·경제적·물리적 측면을 결합한 부동산 개념은 복합개념의 부동산이다. 복합부동산은 토지와 건물이 각각 독립된 부동산이면서 하나의 거래 대상으로 결합된 것을 가리킨다.","c":"중"},"감정평2021_32-82-1":{"f":"필지는 법률적 개념으로 소유권이 미치는 범위에서 지번이 부여된 토지의 등록단위이다.","w":"가격수준이 비슷한 일단의 토지는 지역 또는 획지의 설명이다. 필지는 법률적 개념으로, 하나의 지번이 붙는 토지의 등록단위이다.","c":"중"},"감정평2021_32-82-3":{"f":"공지는 「건축법」에 의한 건폐율·용적률 등의 제한으로 인해 한 필지 내에서 건축하지 않고 비워둔 토지이다.","w":"건폐율·용적률 제한 때문에 한 필지 안에서 건축하지 않고 비워둔 토지는 공지이다. 나지는 건물 등 정착물이 없는 토지이다.","c":"상"},"감정평2021_32-82-4":{"f":"표준지는 지가의 공시를 위해 가치형성요인이 같거나 유사하다고 인정되는 일단의 토지 중에서 선정한 토지이다.","w":"지가 공시를 위해 일단의 토지 중에서 선정하는 토지는 표준지이다. 표본지는 지가변동률을 조사·산정하기 위해 선정한 토지이다.","c":"상"},"감정평2021_32-82-5":{"f":"한계지는 특정의 지점을 기준으로 한 택지이용의 최원방권의 토지이다.","w":"택지이용의 최원방권에 있는 토지는 한계지이다. 공한지는 도시 내 택지 중 지가 상승을 기다리며 장기간 방치된 토지이다.","c":"상"},"감정평2022_33-81-2":{"f":"자연으로서 토지는 인간의 노력에 의해 그 특성을 바꿀 수 있다.","w":"자연으로서의 토지는 개량·이용 같은 인간의 노력으로 특성이 달라질 수 있다고 보는 쪽이 정답 방향으로 추정된다. 원문 표시 자체가 의심스러운 문장이다.","c":"하"},"감정평2023_34-81-2":{"f":"건부지(建敷地)는 건축물의 부지로 이용중인 토지를 말한다.","w":"건부지는 건축물 등이 이미 서 있어 부지로 이용 중인 토지이다. 건축물의 부지로 이용이 가능한 토지까지 넣은 것은 나지·후보지 개념과 섞인 설명이다.","c":"중"},"감정평2023_34-81-3":{"f":"나지(裸地)는 택지 중 정착물이 없는 토지로서 공법상 제한을 받는 토지를 말한다.","w":"나지는 건물 등 정착물이 없는 택지이고, 공법상·사법상 제한을 받는 토지이다. 공법상 제한이 없는 토지라는 말은 틀리다.","c":"상"},"감정평2023_34-81-4":{"f":"제외지(堤外地)는 제방으로부터 하심측으로의 토지를 말한다.","w":"제방으로부터 하천 쪽(하심측)의 토지는 제외지이다. 제내지는 제방으로 보호되는 주거 쪽 토지이다.","c":"상"},"감정평2023_34-81-5":{"f":"일단지(一團地)는 용도상 불가분의 관계에 있는 두 필지 이상의 토지를 말한다.","w":"일단지는 용도상 불가분의 관계에 있는 두 필지 이상의 토지이고, 합병한 토지가 아니다. 합병하면 한 필지가 된다.","c":"상"},"감정평2024_35-83-1":{"f":"민영주택은 국민주택을 제외한 주택을 말한다.","w":"주택법상 민영주택은 국민주택을 제외한 주택이다. 임대주택 제외가 기준이 아니다.","c":"상"},"감정평2024_35-83-2":{"f":"세대구분형 공동주택은 공동주택의 주택 내부 공간의 일부를 세대별로 구분하여 생활이 가능한 구조로 하되, 그 구분된 공간의 일부를 구분소유 할 수 없는 주택으로서 대통령령으로 정하는 건설기준, 설치기준, 면적기준 등에 적합한 주택을 말한다.","w":"세대구분형 공동주택은 구분된 공간을 구분소유 할 수 없다. 구분소유가 가능하면 별개의 공동주택이 된다.","c":"상"},"감정평2024_35-83-4":{"f":"에너지절약형 친환경주택은 저에너지 건물 조성기술 등 대통령령으로 정하는 기술을 이용하여 에너지 사용량을 절감하거나 이산화탄소 배출량을 감소할 수 있도록 건설된 주택을 말한다.","w":"에너지절약형 친환경주택은 에너지 사용량을 줄이고 이산화탄소 배출량도 줄이는 주택이다. 배출량을 늘리는 주택이 아니다.","c":"상"},"감정평2024_35-83-5":{"f":"장수명 주택은 구조적으로 오랫동안 유지ㆍ관리될 수 있는 내구성을 갖추고 있어 내부 구조를 쉽게 변경할 수 있는 주택을 말한다.","w":"장수명 주택은 내구성이 높고 내부 구조를 쉽게 바꿀 수 있는 주택이다. 변경이 어렵다면 장수명 주택의 요건에 맞지 않는다.","c":"상"},"감정평2025_36-81-3":{"f":"“토지의 이동(異動)”이란 토지의 표시를 새로 정하거나 변경 또는 말소하는 것을 말한다.","w":"토지의 이동은 지적공부상 토지의 표시(지목·면적 등)를 새로 정하거나 변경·말소하는 것이다. 홍수·산사태로 지형이 바뀐 사실 자체를 말하지 않는다.","c":"상"},"감정평2026_37-82-3":{"f":"토지에서 경작되는 농작물은 명인방법을 갖추지 않아도 토지와 별개의 물건으로 취급된다.","w":"농작물은 명인방법이 없어도 토지와 독립된 물건으로 취급한다. 명인방법이 필요한 것은 수목이다.","c":"중"},"감정평2026_37-83-5":{"f":"전용면적은 건축물 외벽의 내부선을 기준으로 산정한다.","w":"공동주택의 전용면적은 외벽 내부선을 기준으로 하고, 세대 사이의 벽은 중심선을 기준으로 한다. 외벽 중심선 기준은 아니다.","c":"상"},"감정평2016_27-82-4":{"f":"국토의 계획 및 이용에 관한 법령상 시ㆍ도지사는 보호지구를 문화재, 중요 시설물 및 문화적ㆍ생태적으로 보존가치가 큰 지역의 보호와 보존에 필요하면 그 용도지구의 지정 또는 변경을 도시ㆍ군관리계획으로 결정한다.","w":"문화재·중요시설물·보존가치가 큰 지역의 보호에 쓰는 용도지구는 보호지구이다. 시설보호지구라는 명칭은 현행 지구 체계에 없다.","c":"중"},"감정평2016_27-94-1":{"f":"외부효과는 한 사람의 행위가 제3자의 경제적 후생에 영향을 미치고, 그에 대해 보상이 이루어지지 않는 현상을 말한다.","w":"외부효과는 제3자에게 이익이나 손해를 주면서도 그에 대한 대가나 보상이 오가지 않는 현상이다. 보상을 제3자가 인지하느냐는 개념에 들어가지 않는다.","c":"상"},"감정평2016_27-114-2":{"f":"부동산 거래신고 제도는 부동산 거래신고에 관한 법령에 따라 거래당사자가 부동산등에 관한 매매계약을 체결한 경우 그 실제 매매가격 등을 거래계약 체결일로부터 30일 이내에 그 부동산등의 소재지를 관할하는 시장ㆍ군수 또는 구청장에게 공동 또는 예외적인 경우 단독으로 신고하게 하여 건전하고 투명한 부동산 거래질서를 확립하여 국민경제에 이바지함을 목적으로 한다.","w":"거래신고 기한은 계약 체결일부터 30일 이내이다. 잔금일 기준 60일이 아니다.","c":"상"},"감정평2017_28-81-5":{"f":"공공재는 시장기구에 맡겨둘 경우 비경합성과 비배제성으로 인하여 무임승차(free ride) 현상이 발생할 수 있다.","w":"공공재는 한 사람이 써도 다른 사람이 쓸 수 있고(비경합성) 대가를 내지 않은 사람을 막기 어렵다(비배제성). 그래서 무임승차가 생긴다.","c":"상"},"감정평2018_29-100-3":{"f":"정보의 비대칭성은 시장실패의 원인이다.","w":"거래 당사자 한쪽만 정보를 가지면 역선택·도덕적 해이가 생겨 시장이 실패한다. 공공재, 외부효과, 독점과 함께 시장실패의 대표 원인이다.","c":"상"},"감정평2019_30-85-1":{"f":"토지정책수단 중 토지비축제도, 토지수용은 직접개입방식이고, 금융지원, 보조금 지급은 간접개입방식이다.","w":"토지비축제도와 토지수용은 정부가 직접 토지시장에 개입하는 직접개입방식이다. 금융지원·보조금 지급만 간접개입방식이다.","c":"상"},"감정평2019_30-85-2":{"f":"개발권양도제는 개발이 제한되는 지역의 토지소유권에서 개발권을 분리하여 개발이 필요한 다른 지역에 개발권을 양도할 수 있도록 하는 제도이다.","w":"개발이 제한되는 지역의 개발권을 분리해 다른 지역에 양도하게 하는 제도는 개발권양도제(TDR)이다. 개발부담금제는 개발이익을 환수하는 제도이다.","c":"상"},"감정평2019_30-85-3":{"f":"토지선매에 있어 시장ㆍ군수ㆍ구청장은 토지거래계약허가를 받아 취득한 토지를 그 이용목적대로 이용하고 있지 아니한 토지에 대해서 선매자에게 협의 매수하게 할 수 있다.","w":"토지선매는 선매자로 지정된 자가 토지 소유자와 협의하여 매수하는 제도이다. 강제로 수용하게 하는 제도가 아니다.","c":"상"},"감정평2019_30-85-4":{"f":"개발부담금제는 개발사업의 시행으로 이익을 얻은 사업시행자로부터 개발이익의 일정액을 환수하는 제도이다.","w":"개발사업으로 생긴 개발이익의 일정액을 사업시행자에게서 환수하는 제도는 개발부담금제이다. 개발권양도제는 개발권을 분리해 거래하게 하는 제도이다.","c":"상"},"감정평2019_30-109-1":{"f":"부동산거래 계약과 신고 등에 관한 정보체계 구축의 법적 근거는 「부동산 거래신고 등에 관한 법률」이다.","w":"거래 계약·신고에 관한 정보체계 구축은 부동산 거래신고 등에 관한 법률에 근거한다. 공간정보의 구축 및 관리 등에 관한 법률은 지적·측량 관련 법이다.","c":"중"},"감정평2019_30-109-3":{"f":"국토교통부장관은 적절한 부동산정책의 수립 및 시행을 위하여 부동산 거래상황, 외국인 부동산 취득현황, 부동산 가격 동향 등에 관한 정보를 종합적으로 관리하고, 이를 관련 기관ㆍ단체 등에 제공할 수 있다.","w":"주체는 광역시장·도지사가 아니라 국토교통부장관이다. 제공도 의무가 아니라 할 수 있는 재량이다.","c":"중"},"감정평2019_30-109-4":{"f":"국토교통부장관은 효율적인 정보의 관리 및 국민편의 증진을 위하여 대통령령으로 정하는 바에 따라 부동산거래의 계약ㆍ신고ㆍ허가ㆍ관리 등의 업무와 관련된 정보체계를 구축ㆍ운영할 수 있다.","w":"정보체계를 구축·운영하는 주체는 국토교통부장관이고, 구축·운영은 할 수 있는 규정이다. 광역시장·도지사나 의무로 쓴 부분이 틀리다.","c":"중"},"감정평2019_30-109-5":{"f":"국토교통부장관은 정보체계에 구축되어 있는 정보를 수요자에게 제공할 수 있으며, 이 경우 제공하는 정보의 종류와 내용을 제한할 수 있다.","w":"정보를 제공하더라도 개인정보 보호 등을 위해 제공하는 정보의 종류와 내용은 제한할 수 있다. 제한할 수 없다는 말은 틀리다.","c":"중"},"감정평2020_31-96-5":{"f":"용도지역지구제에 따른 용도 지정 후, 관련법에 의해 사인의 토지이용이 제한된다.","w":"용도지역·지구가 지정되면 건축물 용도, 건폐율, 용적률 등이 법으로 제한되어 사인의 토지이용이 제약을 받는다.","c":"상"},"감정평2023_34-94-1":{"f":"외부효과란 거래 당사자가 시장메카니즘을 통하지 아니하고 상대방에게 미치는 유리하거나 불리한 효과를 말한다.","w":"외부효과는 시장 거래(가격)를 거치지 않고 제3자에게 이익이나 손해를 미치는 것이다. 시장메커니즘을 통해 미치는 효과는 외부효과가 아니다.","c":"상"},"감정평2023_34-94-2":{"f":"부(-)의 외부효과는 의도되지 않은 손해를 주면서 그 대가를 지불하지 않는 외부불경제라고 할 수 있다.","w":"부(-)의 외부효과는 외부불경제이다. 외부경제는 이익을 주고 대가를 받지 못하는 정(+)의 외부효과이다.","c":"상"},"감정평2023_34-94-4":{"f":"정(+)의 외부효과에는 보조금 지급이나 조세경감의 정책이 필요하다.","w":"보조금·조세경감은 과소생산되는 정(+)의 외부효과를 늘리는 정책이다. 부(-)의 외부효과에는 규제나 부담금·조세 부과가 필요하다.","c":"상"},"감정평2023_34-94-5":{"f":"부(-)의 외부효과는 사회적 최적생산량보다 시장생산량이 많은 과다생산을 초래한다.","w":"부(-)의 외부효과는 사회적 비용이 사적 비용보다 커서 시장생산량이 사회적 최적 수준을 넘는 과다생산을 낳는다. 과소생산은 정(+)의 외부효과에서 나타난다.","c":"상"},"감정평2025_36-93-4":{"f":"용도지구는 용도지역의 제한을 강화 또는 완화하여 적용하며, 경관ㆍ안전 등을 도모하기 위하여 도시ㆍ군관리계획으로 결정하는 지역을 말한다.","w":"용도지역이 서로 중복되지 않게 지정되고, 용도지구는 용도지역과 겹쳐 지정할 수 있다. 중복되지 않는다는 요건은 용도지역에 해당한다.","c":"상"},"감정평2025_36-94-3":{"f":"해당 구역에 일정한 면적을 초과하는 토지에 관한 소유권ㆍ지상권(소유권ㆍ지상권의 취득을 목적으로 하는 권리를 포함)을 이전하거나 설정하는 토지거래계약(예약을 포함)에 적용되며, 증여 및 상속은 포함되지 않는다.","w":"토지거래허가는 대가를 받고 이전·설정하는 유상계약에 적용된다. 증여나 상속은 대상이 아니다.","c":"상"},"감정평2025_36-95-3":{"f":"토지의 사유재산권을 인정하되 그 보유ㆍ이용ㆍ개발이 공공복리에 적합해야 한다고 보았다.","w":"토지공개념은 사유재산권을 부정하지 않고, 그 행사가 공공복리에 적합해야 한다고 본다. 사유재산권을 부정하는 것은 사회주의적 토지관이다.","c":"상"},"감정평2016_27-84-1":{"f":"부동성으로 인해 부동산활동을 국지화시키고 임장활동을 필요로 한다.","w":"부동성 때문에 부동산활동은 해당 지역에 국한되고, 현장에 가서 확인하는 임장활동이 필요하다.","c":"상"},"감정평2017_28-96-5":{"f":"토지의 인문적 특성 중에서 도시계획의 변경, 공업단지의 지정 등은 위치의 가변성 중 행정적 위치가 변화하는 예이다.","w":"도시계획 변경, 공업단지 지정은 행정적 위치의 변화이다. 사회적 위치는 인구 증가·도시화 같은 사회 변화에 따른 것이다.","c":"상"},"감정평2019_30-81-3":{"f":"영속성은 토지관리의 필요성을 높여 감정평가에서 수익방식의 이론적 근거가 된다.","w":"영속성이 있어 토지는 미래 수익이 계속 발생하므로 수익환원법의 근거가 되고, 토지에는 물리적 감가가 없다. 원가방식의 근거는 아니다.","c":"중"},"감정평2020_31-81-4":{"f":"용도의 다양성은 토지의 이행과 전환을 가능하게 한다.","w":"토지의 용도 이행·전환을 가능하게 하는 것은 용도의 다양성이다. 합병·분할의 가능성은 면적 조정을 통한 최유효이용과 관련된다.","c":"상"},"감정평2023_34-85-5":{"f":"토지의 소유권은 정당한 이익있는 범위내에서 토지의 상하에 미치며, 한계고도와 한계심도의 범위는 법률로 정하고 있지 않다.","w":"민법상 소유권은 정당한 이익이 있는 범위에서 상하에 미친다. 그 한계고도·한계심도를 정한 법률은 없다.","c":"상"},"감정평2025_36-86-3":{"f":"토지거래허가구역의 지정이나 해제 등으로 인해 주택가격이 하락하거나 상승하는 것은 행정적 위치의 변화에 따른 것이다.","w":"토지거래허가구역 지정·해제는 공법상 규제의 변화이므로 행정적 위치의 변화이다. 경제적 위치는 소득·교통 같은 경제 여건 변화이다.","c":"상"},"감정평2016_27-85-5":{"f":"에스크로우 회사는 매도자와 매수자의 협상과정에 참여하지 않고 거래과정에서 발생하는 여러 가지 문제에 대하여 조언을 하지 않는다.","w":"에스크로우 회사는 중립적인 제3자로서 계약 조건이 이행될 때까지 금전·서류를 보관하고 이전을 처리한다. 협상에 관여하거나 조언하지 않는다.","c":"중"},"감정평2016_27-87-4":{"f":"자료판독을 할 때 환매특약의 등기와 신탁에 관한 등기는 소유권에 관한 사항을 기록하는 부동산 등기부의 갑구에서 그 기재사항을 살펴보아야 한다.","w":"환매특약등기와 신탁등기는 소유권에 관한 사항이므로 갑구에서 확인한다. 을구에는 소유권 이외의 권리(저당권·전세권 등)를 기록한다.","c":"상"},"감정평2016_27-88-1":{"f":"공간정보의 구축 및 관리 등에 관한 법령상 지적도에 기재된 지목의 부호가 「장」으로 표기되어 있어, 분석대상부동산의 지목을 공장용지로 확인ㆍ판단하였다.","w":"공장용지의 지목 부호는 「장」이다. 「공」은 공원의 부호이다.","c":"상"},"감정평2016_27-88-2":{"f":"용수 또는 배수를 위하여 일정한 형태를 갖춘 인공적인 수로ㆍ둑 및 그 부속시설물의 부지와 자연의 유수가 있거나 있을 것으로 예상되는 소규모 수로부지를 공간정보의 구축 및 관리 등에 관한 법령상의 지목인 구거로 확인ㆍ판단하였다.","w":"인공 수로·둑 및 부속시설물의 부지와 소규모 수로부지는 구거이다. 하천은 자연의 유수가 있거나 있을 것으로 예상되는 토지이다.","c":"상"},"감정평2016_27-88-3":{"f":"부동산경매에서 경락허가결정 확정 후 경매대금을 완납한 때에 경락인은 등기를 하지 않아도 목적부동산의 소유권을 취득하는 것으로 확인ㆍ판단하였다.","w":"경매로 인한 부동산 취득은 민법 제187조에 따라 등기 없이 효력이 생기므로, 매수인은 대금을 다 낸 때 소유권을 취득한다.","c":"상"},"감정평2016_27-88-4":{"f":"국토의 계획 및 이용에 관한 법령상 토지이용계획확인서를 통해 공법상 이용제한 및 거래규제 사항을 확인ㆍ판단하였다.","w":"토지이용계획확인서에서는 용도지역·지구와 같은 공법상 이용제한과 거래규제를 확인한다. 건물의 소재지·구조·용도는 건축물대장에서 확인한다.","c":"상"},"감정평2016_27-117-1":{"f":"포지셔닝(Positioning)은 목표시장에서 고객의 욕구를 파악하여 경쟁 제품과 차별성을 가지도록 제품 개념을 정하고 소비자의 지각 속에 적절히 위치시키는 것이다.","w":"경쟁 제품과 차별되게 제품 개념을 정해 소비자 인식 속에 자리 잡게 하는 활동은 포지셔닝이다. 표적시장은 선택한 세분시장이다.","c":"상"},"감정평2016_27-117-2":{"f":"표적시장(Target market)은 세분화된 시장 중 가장 좋은 시장기회를 제공해 줄 수 있는 특화된 시장이다.","w":"세분화된 시장 중 가장 좋은 기회를 줄 시장을 고른 것이 표적시장이다. 포지셔닝은 그 시장에서 제품의 위치를 정하는 일이다.","c":"상"},"감정평2016_27-117-3":{"f":"4P에 의한 마케팅 믹스 전략의 구성요소는 제품(Product), 유통경로(Place), 판매 촉진(Promotion), 가격(Price)이다.","w":"4P는 제품·가격·유통경로·판매촉진이다. 포지셔닝은 STP 전략의 단계이다.","c":"상"},"감정평2016_27-117-4":{"f":"STP란 시장세분화(Segmentation), 표적화(Targeting), 포지셔닝(Positioning)을 표상하는 약자이다.","w":"STP의 P는 포지셔닝이다. 가격(Price)은 4P의 구성요소이다.","c":"상"},"감정평2017_28-100-1":{"f":"부동산의 상태 또는 사실관계, 등기능력 없는 권리 및 등기를 요하지 않는 권리 관계 등 자세한 내용에 이르기까지 분석의 대상으로 하는 것이 최광의의 권리분석이다.","w":"사실관계와 등기를 요하지 않는 권리까지 모두 분석하는 것은 최광의의 권리분석이다. 협의의 권리분석은 등기능력 있는 권리의 하자 여부를 다룬다.","c":"상"},"감정평2017_28-115-2":{"f":"고객점유마케팅전략은 AIDA원리로 대표되는 소비자중심의 마케팅전략이다.","w":"AIDA 원리로 대표되는 소비자 중심 마케팅은 고객점유마케팅전략이다. 시장점유마케팅전략은 공급자 중심이며 STP와 4P Mix를 쓴다.","c":"상"},"감정평2018_29-107-4":{"f":"시장점유마케팅전략에 해당되는 4P MIX전략은 유통경로(place), 제품(product), 가격(price), 판매촉진(promotion)으로 구성된다.","w":"4P MIX는 시장점유마케팅전략에 속하고, 구성은 제품·가격·유통경로·판매촉진이다. 위치선점(포지셔닝)은 STP의 단계이다.","c":"상"},"감정평2019_30-116-1":{"f":"고객점유마케팅전략은 AIDA원리에 기반을 두면서 소비자의 욕구를 파악하여 마케팅효과를 극대화하는 전략이다.","w":"AIDA 원리에 기반을 두는 소비자 욕구 중심 전략은 고객점유마케팅전략이다. 시장점유마케팅전략은 공급자 중심이다.","c":"상"},"감정평2019_30-116-2":{"f":"시장점유마케팅전략은 공급자 중심의 마케팅 전략으로 표적시장을 선정하거나 틈새시장을 점유하는 전략이다.","w":"공급자 중심으로 표적시장·틈새시장을 점유하는 전략은 시장점유마케팅전략이다. 고객점유마케팅전략은 소비자 중심이다.","c":"상"},"감정평2019_30-116-4":{"f":"STP전략은 시장세분화(Segmentation), 표적시장 선정(Targeting), 포지셔닝(Positioning)으로 구성된다.","w":"STP의 세 번째 요소는 포지셔닝이다. 판매촉진(Promotion)은 4P 믹스의 요소이다.","c":"상"},"감정평2019_30-116-5":{"f":"4P-Mix전략은 제품(Product), 가격(Price), 유통경로(Place), 판매촉진(Promotion)으로 구성된다.","w":"4P의 마지막 요소는 판매촉진이다. 포지셔닝은 STP에 속한다.","c":"상"},"감정평2019_30-117-1":{"f":"일반중개계약은 중개의뢰인이 다수의 개업공인중개사에게 의뢰하는 계약의 형태이다.","w":"다수의 개업공인중개사에게 동시에 의뢰할 수 있는 것은 일반중개계약이다. 순가중개계약은 의뢰인이 제시한 가격을 넘는 초과액을 중개사가 보수로 갖는 방식이다.","c":"상"},"감정평2019_30-117-2":{"f":"독점중개계약을 체결한 개업공인중개사는 누가 거래를 성립시켰는지에 상관없이 중개보수를 받을 수 있다.","w":"독점중개계약에서는 의뢰인이 직접 거래를 성립시켜도 개업공인중개사가 중개보수를 받는다. 중개사가 직접 성립시키지 않았다는 이유로 보수를 못 받는 것이 아니다.","c":"상"},"감정평2019_30-117-3":{"f":"전속중개계약을 체결한 개업공인중개사는 의뢰인이 직접 거래를 성립시킨 경우에는 중개보수를 받을 수 없다.","w":"전속중개계약은 다른 중개사에게 의뢰하지 못하게 하되, 의뢰인이 직접 성립시킨 거래에는 보수를 청구하지 못한다. 누가 성립시켰든 받는 것은 독점중개계약이다.","c":"중"},"감정평2019_30-117-5":{"f":"순가중개계약은 거래가격을 정하여 개업공인중개사에게 제시하고, 이를 초과한 가격으로 거래가 이루어진 경우 그 초과액을 개업공인중개사가 중개보수로 획득하는 방법이다.","w":"의뢰인이 정한 가격을 초과한 금액을 중개사가 보수로 가져가는 방식은 순가중개계약이다. 일반중개계약은 다수에게 동시에 의뢰하는 방식이다.","c":"상"},"감정평2020_31-117-1":{"f":"공인중개사법에 의한 공인중개사자격을 취득한 자를 공인중개사라고 말한다.","w":"자격을 취득한 사람은 공인중개사이다. 개업공인중개사는 중개사무소 개설등록을 한 사람(또는 법인)이다.","c":"상"},"감정평2020_31-117-2":{"f":"선박법 및 선박등기법에 따라 등기된 20톤 이상의 선박은 공인중개사법에 의한 중개 대상물이 아니다.","w":"공인중개사법상 중개대상물은 토지, 건축물, 입목, 공장재단, 광업재단이다. 선박은 등기되어 있어도 포함되지 않는다.","c":"상"},"감정평2020_31-117-3":{"f":"개업공인중개사에 소속된 공인중개사인 자로서 중개업무를 수행하는 자는 소속공인중개사이다.","w":"개업공인중개사에 소속되어 중개업무를 수행하거나 보조하는 공인중개사가 소속공인중개사이다. 아니라고 한 부분이 틀리다.","c":"상"},"감정평2020_31-117-5":{"f":"중개보조원이란 공인중개사가 아닌 자로서 개업공인중개사에 소속되어 중개업무와 관련된 단순한 업무를 보조하는 자를 말한다.","w":"중개보조원은 개업공인중개사에 소속되어 현장 안내, 서무 같은 단순 업무를 보조하는 자이다. 스스로 중개업을 하는 자가 아니다.","c":"상"},"감정평2020_31-118-5":{"f":"거래당사자가 부동산의 거래신고를 한 후 해당 거래계약이 취소된 경우에는 취소가 확정된 날부터 30일 이내에 해당 신고관청에 단독 또는 공동으로 신고하여야 한다.","w":"거래계약이 해제·무효·취소된 경우에는 확정된 날부터 30일 이내에 단독 또는 공동으로 신고한다. 60일 이내 공동 신고가 아니다.","c":"중"},"감정평2021_32-112-5":{"f":"부동산 권리분석을 행하는 주체가 분석대상권리의 주요한 사항을 직접 확인해야 한다는 탐문주의의 원칙은 권리분석활동을 하는 데 지켜야 할 이념이다.","w":"분석 주체가 주요 사항을 직접 확인해야 한다는 원칙은 탐문주의이다. 증거주의는 조사 결과를 증거로 뒷받침한다는 원칙이다.","c":"상"},"감정평2022_33-106-5":{"f":"AIDA 원리에 따르면 소비자의 구매의사결정은 주의(Attention), 관심(Interest), 욕망(Desire), 행동(Action)의 단계를 순차적으로 거친다.","w":"AIDA의 순서는 주의, 관심, 욕망, 행동이다. 행동이 처음에 오는 순서가 아니다.","c":"상"},"감정평2022_33-108-4":{"f":"은행이나 신탁회사도 해당 업무를 취급할 수 있다.","w":"에스크로우 업무는 은행이나 신탁회사도 취급할 수 있다. 전문 에스크로우 회사만 하는 것이 아니다.","c":"중"},"감정평2022_33-109-1":{"f":"순가중개계약에서는 매도자가 개업공인중개사에게 제시한 가격을 초과해 거래가 이루어진 경우 그 초과액을 개업공인중개사가 중개보수로 갖는다.","w":"순가중개계약에서는 의뢰인이 제시한 가격을 초과한 금액 전부를 개업공인중개사가 보수로 가진다. 나누어 갖는 방식이 아니다.","c":"상"},"감정평2022_33-113-3":{"f":"임장활동 이전 단계 활동으로 여러 가지 물적 증거를 수집하고 탁상으로 검토하여 1차적으로 하자의 유무를 발견하는 작업을 자료판독이라고 한다.","w":"임장활동 전에 공부 등 자료를 모아 탁상에서 1차로 하자를 찾는 작업은 자료판독으로 보는 것이 맞다고 추정한다. 권리보증은 별개의 개념이다.","c":"하"},"감정평2023_34-104-1":{"f":"시장세분화는 가격차별화, 최적의사결정, 상품차별화 등에 기초하여 부동산시장을 서로 다른 둘 또는 그 이상의 하위시장으로 묶는 과정이다.","w":"시장세분화는 전체 시장을 서로 다른 둘 이상의 하위시장으로 나누는 과정이다. 상위시장으로 묶는 것이 아니다.","c":"상"},"감정평2023_34-112-2":{"f":"현재 예고등기제는 「부동산등기법」상 폐지되었으나, 환매(특약)등기제는 존속한다.","w":"예고등기제는 2011년 부동산등기법 개정으로 폐지되었다. 환매특약등기는 지금도 할 수 있다.","c":"상"},"감정평2024_35-82-4":{"f":"개업공인중개사는 대통령령으로 정하는 기준과 절차에 따라 등록관청에 신고하고 그 관할 구역 외의 지역에 분사무소를 둘 수 있다.","w":"분사무소는 등록관청의 허가가 아니라 신고로 설치한다.","c":"중"},"감정평2024_35-115-3":{"f":"세분시장은 개념적으로 구분될 수 있으며 마케팅 믹스 요소에 대해 서로 다르게 반응한다.","w":"세분시장은 마케팅 믹스에 대해 서로 다르게 반응하는 시장이다. 동일하게 반응하면 시장을 나눌 이유가 없다.","c":"상"},"감정평2025_36-103-5":{"f":"AIDA 원리는 고객의 구매의사 결정단계를 심리적 발전단계에 맞춘 것으로 주목(Attention), 관심(Interest), 욕망(Desire), 행동(Action)의 순서를 거친다.","w":"AIDA의 순서는 주목, 관심, 욕망, 행동이다. 행동은 맨 마지막이다.","c":"상"},"감정평2025_36-114-3":{"f":"유지(溜池)는 물이 고이거나 상시적으로 물을 저장하고 있는 저수지·호수 등의 토지로 지적도에는 ‘유’로 표기한다.","w":"유지는 물이 고이거나 물을 저장하는 저수지·호수·연못 등의 토지이다. 자연의 유수가 있는 토지는 하천이다.","c":"상"},"감정평2026_37-87-1":{"f":"임차권과 권리질권은 등기할 수 있다.","w":"부동산등기법상 등기할 수 있는 권리에는 소유권, 지상권, 지역권, 전세권, 저당권, 권리질권, 채권담보권, 임차권이 있다.","c":"상"},"감정평2026_37-87-2":{"f":"「부동산등기법」상 예고등기제는 현재 폐지되었다.","w":"예고등기제는 2011년 개정으로 폐지되어 지금은 시행되지 않는다.","c":"상"},"감정평2026_37-87-3":{"f":"부동산의 등기기록에는 표제부, 갑구, 을구를 둔다.","w":"등기기록은 표제부, 갑구, 을구로 이루어진다. 병구는 없다.","c":"상"},"감정평2026_37-87-4":{"f":"등기권리의 순위는 등기기록 중 다른 구(區)에서 한 등기 상호간에는 접수번호에 따른다.","w":"같은 구 안의 등기는 순위번호로, 다른 구에서 한 등기끼리는 접수번호로 순위를 정한다.","c":"상"},"감정평2016_27-89-1":{"f":"불규칙적 변동은 예기치 못한 사태로 초래되는 비순환적 경기변동 현상을 말한다.","w":"예기치 못한 사태로 생기는 비순환적 변동은 불규칙(우발적) 변동이다. 계절적 변동은 계절에 따라 반복되는 변동이다.","c":"상"},"감정평2017_28-119-4":{"f":"실수요 증가에 의한 공급부족이 발생하는 경우 공인중개사는 매도자를 확보해 두려는 경향을 보인다.","w":"공급이 부족한 상황에서는 매수자가 넘치므로 중개사는 팔 물건을 내놓는 매도자를 확보하려 한다.","c":"중"},"감정평2016_27-90-2":{"f":"1사분면은 부동산 임대료와 공간재고량의 관계를 나타낸다.","w":"1사분면은 임대료와 공간재고(공간시장)를 나타낸다. 자산가격은 2사분면과 3사분면에서 다룬다.","c":"상"},"감정평2017_28-110-1":{"f":"부동산의 수요는 유효수요의 개념으로, 단순히 부동산을 구입하고자 하는 의사만을 의미하지 않는다.","w":"부동산 수요는 구매 의사와 구매 능력을 함께 갖춘 유효수요이다.","c":"상"},"감정평2017_28-110-2":{"f":"건축비의 하락 등 생산요소 가격의 하락은 주택공급곡선을 오른쪽으로 이동시킨다.","w":"생산요소 가격이 내리면 같은 가격에서 공급량이 늘어 공급곡선이 오른쪽으로 이동한다.","c":"상"},"감정평2017_28-110-3":{"f":"수요자의 소득이 변하여 수요곡선 자체가 이동하는 경우는 수요의 변화에 해당한다.","w":"소득 같은 가격 이외의 요인으로 수요곡선 자체가 이동하면 수요의 변화이다. 수요량의 변화는 가격 변화로 곡선 위에서 움직이는 것이다.","c":"상"},"감정평2017_28-110-4":{"f":"인구의 증가로 부동산 수요가 증가하는 경우 균형가격은 상승하고, 균형량은 증가한다.","w":"수요곡선이 오른쪽으로 이동하면 균형가격과 균형량이 모두 증가한다.","c":"상"},"감정평2020_31-93-4":{"f":"4사분면에서는 신규 부동산의 건설량과 재고의 멸실량이 같아야 부동산공간시장의 균형을 이룰 수 있다.","w":"4사분면에서 신규 건설량은 재고에서 멸실되는 양과 같아야 재고가 변하지 않고 균형을 이룬다.","c":"상"},"감정평2022_33-85-1":{"f":"장기균형에서 4개의 내생변수, 즉 공간재고, 임대료, 자산가격, 건물의 신규공급량이 결정된다.","w":"4사분면 모형의 내생변수는 공간재고, 임대료, 자산가격, 신규건설량이다. 자본환원율은 외생변수이다.","c":"상"},"감정평2024_35-85-3":{"f":"새로운 장기균형에서 균형공간재고는 증가한다.","w":"건설비용이 내려 신규건설량이 늘어나므로 새 장기균형의 공간재고는 증가한다. 그 결과 임대료와 자산가격은 내린다.","c":"상"},"감정평2024_35-102-5":{"f":"공급의 가격탄력성이 작을수록 수요변화시 균형가격의 변동폭은 크지만 균형거래량의 변동폭은 작다.","w":"공급이 비탄력적이면 수요가 변해도 공급량이 따라 늘지 못해 가격 변동이 크고 거래량 변동은 작다.","c":"상"},"감정평2024_35-107-1":{"f":"수요의 증가폭이 공급의 증가폭보다 클 경우, 균형가격은 상승하고 균형거래량은 증가한다.","w":"수요가 공급보다 더 크게 늘면 가격은 오르고, 둘 다 증가하므로 거래량도 증가한다.","c":"상"},"감정평2025_36-87-4":{"f":"수요와 공급이 동시에 감소하는 경우, 공급의 감소폭이 수요의 감소폭보다 크면, 균형 가격은 상승하고 균형거래량은 감소한다.","w":"공급이 수요보다 더 크게 줄면 가격은 오르고, 둘 다 감소하므로 거래량은 줄어든다.","c":"상"},"감정평2026_37-92-1":{"f":"임대료, 자산가격, 신규건설량, 공간재고 등 4개 내생변수의 장기균형이 결정된다.","w":"4사분면 모형의 내생변수는 임대료, 자산가격, 신규건설량, 공간재고이다. 건설비용은 외생변수이다.","c":"상"},"감정평2026_37-92-2":{"f":"지역경제변수인 소득, 인구 또는 고용이 증가하면 부동산공간시장에서 임대료는 단기적으로 상승한다.","w":"소득·인구·고용이 늘면 공간수요가 늘어 단기에는 임대료가 오른다.","c":"상"},"감정평2026_37-92-3":{"f":"부동산자산시장에서 자본환원율은 자본투자에 대한 요구수익률을 의미하는 외생변수이다.","w":"자본환원율은 요구수익률을 뜻하는 외생변수이다. 자산가격은 임대료를 자본환원율로 나눈 값으로 내생변수이다.","c":"상"},"감정평2026_37-92-4":{"f":"건물의 신규건설량과 재고의 멸실량이 일치할 때 장기균형에 도달한다.","w":"장기균형은 신규건설량이 멸실량과 같아 재고가 변하지 않을 때 이루어진다. 최초 공간재고와의 일치는 조건이 아니다.","c":"중"},"감정평2016_27-91-4":{"f":"신탁계약은 위탁자와 수탁자 간에 체결되며 투자자는 위탁자가 발행하는 수익증권을 매입함으로써 수익자가 되어 운용성과를 얻을 수 있게 된다.","w":"투자신탁의 신탁계약은 위탁회사와 수탁회사 사이에 맺는다. 수익자와 위탁자 사이의 계약이 아니다.","c":"중"},"감정평2016_27-109-2":{"f":"위탁관리 부동산투자회사 및 기업구조조정 부동산투자회사의 설립 자본금은 3억원 이상으로 한다.","w":"위탁관리·기업구조조정 부동산투자회사의 설립 자본금은 3억원 이상이다. 10억원이 아니다.","c":"상"},"감정평2016_27-109-3":{"f":"자기관리 부동산투자회사의 설립 자본금은 5억원 이상으로 한다.","w":"자기관리 부동산투자회사의 설립 자본금은 5억원 이상이다. 3억원은 위탁관리·기업구조조정 리츠의 기준이다.","c":"상"},"감정평2016_27-109-4":{"f":"영업인가를 받은 날부터 6개월이 지난 위탁관리 부동산투자회사 및 기업구조조정 부동산투자회사의 자본금은 50억원 이상이 되어야 한다.","w":"영업인가 후 6개월이 지난 위탁관리·기업구조조정 리츠의 최저자본금은 50억원이다. 자기관리 리츠는 70억원이다.","c":"상"},"감정평2016_27-109-5":{"f":"부동산투자회사는 부동산 등 자산의 운용에 관하여 회계처리를 할 때에는 금융위원회가 정하는 회계처리기준에 따라야 한다.","w":"리츠의 회계처리는 금융위원회가 정하는 기준에 따른다. 국토교통부 기준이라는 말은 틀리다.","c":"중"},"감정평2017_28-86-4":{"f":"PF는 위험분담을 위해 여러 이해관계자가 계약관계에 따라 참여하므로, 일반개발 사업에 비해 사업진행이 복잡하고 시간이 더 걸린다.","w":"프로젝트 파이낸싱은 이해관계자가 많고 계약관계가 복잡해 일반 개발사업보다 사업 진행이 더디다. 신속하다는 말은 틀리다.","c":"중"},"감정평2018_29-96-2":{"f":"부동산투자회사는 발기설립의 방법으로 하여야 하며, 현물출자에 의한 설립이 불가능하다.","w":"부동산투자회사는 발기설립만 가능하고 설립 시 현물출자는 할 수 없다.","c":"중"},"감정평2019_30-94-2":{"f":"저당담보부채권(MBB)은 모기지풀에서 발생하는 현금흐름과 관련된 위험을 발행자가 부담하는 채권이다.","w":"MBB는 모기지 소유권이 발행기관에 남고, 조기상환·채무불이행 위험도 발행기관이 진다. 위험이 투자자에게 넘어가는 것은 MPTB·MBS(지분형)이다.","c":"중"},"감정평2019_30-95-4":{"f":"해당 프로젝트가 부실화되면 대출기관의 채권회수에 영향을 받는다.","w":"프로젝트 파이낸싱은 프로젝트의 현금흐름과 자산을 상환 재원으로 삼는 비소구 또는 제한소구 금융이다. 프로젝트가 부실해지면 대출기관의 회수가 줄어든다.","c":"상"},"감정평2020_31-102-2":{"f":"지불이체채권(MPTB)의 모기지 소유권은 발행자에게 있고, 원리금 수취권은 투자자에게 이전된다.","w":"MPTB는 모기지 소유권은 발행자가 갖고 원리금 수취권만 투자자에게 넘긴다. 반대로 적은 문장이다.","c":"상"},"감정평2020_31-102-3":{"f":"저당담보부채권(MBB)의 조기상환위험과 채무불이행 위험은 발행자가 부담한다.","w":"MBB의 위험은 발행자가 부담한다. 투자자는 정해진 이자와 원금을 받는다.","c":"상"},"감정평2020_31-102-4":{"f":"다계층증권(CMO)은 채권형증권으로 구성되어 있다.","w":"CMO는 같은 저당풀에서 만기와 이자율이 다른 여러 계층의 채권을 발행하는 증권이다. 지분형증권으로만 구성되지 않는다.","c":"상"},"감정평2020_31-102-5":{"f":"상업용 저당증권(CMBS)은 공적 유동화중개기관을 통하지 않고 민간 금융기관이 발행하기도 한다.","w":"CMBS는 상업용 부동산 담보 대출채권을 기초로 민간에서도 발행한다. 반드시 공적 유동화중개기관을 거쳐야 하는 것은 아니다.","c":"중"},"감정평2020_31-103-3":{"f":"차입자(사업주)의 입장에서는 부외금융(off-balance sheet financing)에 의해 채무수용능력이 커지는 장점이 있다.","w":"부외금융은 차입자의 재무상태표에 부채로 잡히지 않으므로 차입자의 채무수용능력이 커진다. 금융기관 입장에서 얻는 이점이 아니다.","c":"상"},"감정평2021_32-101-3":{"f":"부동산개발PF ABCP(Asset Backed Commercial Paper)는 부동산개발PF ABS(Asset Backed Securities)에 비해 만기가 짧고, 대부분 사모로 발행된다.","w":"ABCP는 단기 어음이라 만기가 짧고 사모로 발행되는 것이 대부분이다. 만기가 길고 공모라는 설명은 ABS 쪽에 가깝다.","c":"중"},"감정평2022_33-94-1":{"f":"최저자본금준비기간이 지난 위탁관리 부동산투자회사의 자본금은 50억원 이상이 되어야 한다.","w":"최저자본금준비기간이 지난 뒤 위탁관리 리츠는 50억원, 자기관리 리츠는 70억원 이상이어야 한다(부동산투자회사법 제10조).","c":"상"},"감정평2022_33-94-2":{"f":"자기관리 부동산투자회사의 설립자본금은 5억원 이상으로 한다.","w":"자기관리 리츠의 설립자본금은 5억원 이상이다. 3억원은 위탁관리·기업구조조정 리츠의 기준이다.","c":"상"},"감정평2022_33-94-3":{"f":"자기관리 부동산투자회사에 자산운용 전문인력으로 상근하는 감정평가사는 해당분야에 5년 이상 종사한 사람이어야 한다.","w":"자기관리 리츠의 자산운용 전문인력인 감정평가사·공인중개사는 해당 분야 종사 경력이 5년 이상이어야 한다. 3년 이상이 아니다.","c":"중"},"감정평2022_33-94-4":{"f":"최저자본금준비기간이 끝난 후에는 매 분기 말 현재 총자산의 100분의 70 이상이 부동산(건축 중인 건축물 포함)이어야 한다.","w":"총자산의 100분의 80 이상을 부동산·부동산 관련 증권·현금으로 구성하고, 이 중 100분의 70 이상은 부동산이어야 한다(부동산투자회사법 제25조 제1항).","c":"상"},"감정평2022_33-100-3":{"f":"저당담보부채권(MBB)의 발행자는 채무불이행위험을 부담한다.","w":"MBB는 발행자가 모기지를 보유하며 채무불이행위험을 부담한다. 투자자가 부담하지 않는다.","c":"상"},"감정평2023_34-102-1":{"f":"프로젝트의 자산 또는 신용을 바탕으로 자금을 조달하고, 프로젝트의 수익으로 원리금을 상환하거나 수익을 배당하는 방식의 자금조달기법이다.","w":"프로젝트 파이낸싱은 기업 전체가 아니라 해당 프로젝트의 자산·미래 현금흐름을 바탕으로 자금을 조달한다.","c":"상"},"감정평2023_34-102-2":{"f":"프로젝트 사업주는 기업 또는 개인일 수 있으며, 법인도 될 수 있다.","w":"프로젝트 사업주는 법인, 기업, 개인 모두 될 수 있다.","c":"중"},"감정평2023_34-102-3":{"f":"프로젝트 사업주는 대출기관으로부터 상환청구를 받지는 않으며, 이러한 방식으로 조달한 부채는 사업주의 재무상태표에는 부채로 계상되지 않는다.","w":"프로젝트 파이낸싱은 부외금융이라 사업주의 재무상태표에 부채로 잡히지 않는다.","c":"상"},"감정평2023_34-102-4":{"f":"프로젝트 회사가 파산 또는 청산할 경우, 채권자들은 프로젝트 사업주에 대해 원리금상환을 청구할 수 없다.","w":"비소구금융이므로 프로젝트 회사가 파산해도 채권자는 사업주에게 원리금 상환을 청구하지 못한다. 청구는 프로젝트 회사의 자산과 현금흐름 범위에서 한다.","c":"중"},"감정평2023_34-108-5":{"f":"부동산담보신탁은 저당권 설정보다 소요되는 경비가 많고, 채무불이행 시 부동산 처분 절차가 간편하다.","w":"담보신탁은 수수료와 신탁등기 비용 때문에 저당권 설정보다 경비가 더 들지만, 채무불이행 시 공매 등으로 처분 절차가 간편하고 빠르다.","c":"중"},"감정평2024_35-105-1":{"f":"사업주의 대차대조표에 부채로 표시되지 않아 사업주의 부채비율에 영향을 미치지 않는다.","w":"프로젝트 파이낸싱은 부외금융이므로 사업주의 재무상태표에 부채로 표시되지 않는다. 그래서 사업주의 부채비율에 영향이 없다.","c":"상"},"감정평2024_35-108-3":{"f":"부동산투자회사는 부동산 등 자산의 운용에 관하여 회계처리를 할 때에는 금융위원회가 정하는 회계처리기준에 따라야 한다.","w":"리츠의 회계처리는 금융위원회가 정하는 기준에 따른다. 금융감독원이 정하는 기준이라는 말은 틀리다.","c":"중"},"감정평2026_37-105-1":{"f":"소액으로 투자가 가능한 부동산 간접투자상품이다.","w":"리츠는 주식을 사서 소액으로 투자하는 간접투자상품이다. 직접투자상품이 아니다.","c":"상"},"감정평2026_37-106-2":{"f":"저당이체채권(MPTB)의 발행자는 채무불이행위험을 부담하며 투자자는 조기상환위험을 부담한다.","w":"MPTB는 발행자가 채무불이행위험을, 투자자가 조기상환위험을 부담한다. 두 위험의 부담자가 반대로 적혔다.","c":"중"},"감정평2026_37-106-3":{"f":"저당담보부채권(MBB)의 발행자는 금리위험과 채무불이행위험을 부담한다.","w":"MBB는 발행자가 위험을 부담한다. 투자자는 이를 부담하지 않는다.","c":"상"},"감정평2026_37-106-4":{"f":"다른 조건이 일정할 때 시장금리가 표면금리보다 높은 경우 저당담보부채권(MBB)의 발행가격은 낮아진다.","w":"시장금리가 표면금리보다 높으면 채권은 액면보다 낮은 가격에 발행된다.","c":"상"},"감정평2026_37-106-5":{"f":"다른 조건이 일정할 때 저당이체채권(MPTB)의 듀레이션(duration)은 조기상환이 많이 일어난 경우가 조기상환이 없는 경우보다 짧다.","w":"조기상환이 많으면 원금이 일찍 돌아와 평균 회수기간(듀레이션)이 짧아진다.","c":"상"},"감정평2026_37-120-5":{"f":"담보신탁은 금융기관 입장에서 부동산관리가 자유로우나 법원 경매에 비해 환가절차가 간편하다.","w":"담보신탁은 신탁회사가 공매 등으로 처분하므로 법원 경매보다 환가절차가 간편하다. 복잡하다는 말은 틀리다.","c":"중"},"감정평2016_27-96-1":{"f":"부동산개발업의 관리 및 육성에 관한 법령상 부동산개발이란 토지를 건설공사의 수행 또는 형질변경의 방법으로 조성하는 행위를 말하며, 시공을 담당하는 행위는 제외한다.","w":"법령상 부동산개발에서 시공을 담당하는 행위는 제외된다. 시공까지 포함한다고 쓴 것이 틀리다.","c":"상"},"감정평2017_28-107-4":{"f":"부동산 개발과정의 시장분석은 속성상 지리적ㆍ공간적 범위에 국한되며, 대상 개발사업의 경쟁력 분석에 한하지 않는다.","w":"시장분석은 시장지역이라는 지리적·공간적 범위 안에서 수요·공급을 분석한다. 범위에 국한되지 않는다거나 사업 경쟁력 분석에 한정된다는 말은 틀리다.","c":"중"},"감정평2018_29-108-5":{"f":"입지분석은 부동산개발에 영향을 미치는 인근 환경요소의 현황과 전망을 분석하는 과정이다.","w":"인근 환경요소의 현황과 전망을 분석하는 것은 입지(지역)분석이다. 투자결정분석은 사업의 수익성·투자 여부를 판단하는 단계이다.","c":"중"},"감정평2019_30-111-4":{"f":"BTL방식은 초등학교 교사 신축사업에 적합한 방식이다.","w":"사용료를 받아 수익을 내기 어려운 학교 시설은 정부가 임대료를 지급하는 BTL이 맞다. BTO는 도로·터널처럼 이용자 사용료로 투자비를 회수하는 시설에 쓴다.","c":"상"},"감정평2019_30-115-1":{"f":"「부동산개발업의 관리 및 육성에 관한 법률」상 부동산개발은 시공을 담당하는 행위를 포함하지 않는다.","w":"부동산개발의 정의에서 시공을 담당하는 행위는 제외된다.","c":"상"},"감정평2020_31-100-5":{"f":"후분양은 개발업자의 시장위험을 증가시킨다.","w":"후분양은 건물 준공 후 분양하므로 개발업자가 자금조달 부담과 분양시장 변동위험을 더 진다. 선분양이 시장위험을 줄인다.","c":"중"},"감정평2021_32-107-1":{"f":"환지방식은 수용방식에 비해 종전 토지소유자에게 개발이익이 귀속될 가능성이 큰 편이다.","w":"환지방식은 종전 토지소유자가 토지를 제공하고 개발 후 땅을 돌려받아 개발이익이 소유자에게 귀속된다. 수용방식은 보상으로 끝나 이익이 사업시행자에게 간다.","c":"상"},"감정평2025_36-104-2":{"f":"「개발이익 환수에 관한 법률」상 “개발이익”이란 개발사업의 시행이나 토지이용계획의 변경, 그 밖에 사회적ㆍ경제적 요인에 따라 정상지가(正常地價)상승분을 초과하여 개발사업을 시행하는 자나 토지 소유자에게 귀속되는 토지 가액의 증가분을 말한다.","w":"개발이익의 귀속 주체는 개발사업을 시행하는 자와 토지 소유자이다. 토지 점유자가 아니다.","c":"상"},"감정평2016_27-93-2":{"f":"원리금균등분할상환방식의 원리금은 대출금에 저당상수를 곱하여 산출한다.","w":"원리금균등상환액은 대출금에 저당상수를 곱해 구한다. 감채기금계수는 목표금액을 모으기 위한 적립액을 구할 때 쓴다.","c":"상"},"감정평2017_28-87-1":{"f":"단독주택, 다세대주택, 상가주택 등이 연금의 대상주택이 된다.","w":"(출제 당시 기준 X. 현행은 주거목적 오피스텔도 대상에 포함되는지 확인 필요) 주택연금은 공시가격 상한 이하의 주택이 대상이고, 상가주택은 주택 부분이 절반 이상일 때만 가능하다. 오피스텔은 출제 당시 대상이 아니었다.","c":"하"},"감정평2018_29-98-1":{"f":"주택소유자 또는 그 배우자가 55세 이상이면 이용할 수 있다.","w":"주택연금은 주택소유자나 배우자 중 한 명이 일정 연령(현행 55세) 이상이면 가입할 수 있다. 부부 모두 60세 이상이어야 한다는 요건은 없다.","c":"중"},"감정평2019_30-91-1":{"f":"예상치 못한 인플레이션이 발생할 경우 대출기관에게 유리한 유형은 변동금리대출이다.","w":"예상 못한 인플레이션이 오면 고정금리대출은 실질 수익이 줄어 대출기관에 불리하다. 변동금리는 이자율을 올릴 수 있어 유리하다.","c":"상"},"감정평2019_30-91-2":{"f":"일반적으로 대출일 기준 시 이자율은 고정금리대출이 변동금리대출보다 높다.","w":"고정금리는 금리 변동위험을 대출기관이 지므로 대출 시점 이자율이 변동금리보다 높다.","c":"상"},"감정평2019_30-91-4":{"f":"변동금리대출은 시장상황에 따라 이자율을 변동시킬 수 있으므로 기준금리 외에 가산금리도 고려한다.","w":"변동금리대출의 이자율은 기준금리에 가산금리를 더해 정한다. 가산금리를 고려하지 않는다는 말은 틀리다.","c":"상"},"감정평2019_30-91-5":{"f":"변동금리대출의 경우 시장이자율 상승 시 이자율 조정주기가 짧을수록 대출기관에게 유리하다.","w":"조정주기가 짧으면 시장이자율 상승을 빨리 반영해 대출기관에 유리하다.","c":"상"},"감정평2020_31-104-1":{"f":"원리금균등분할상환(CPM) 방식의 경우, 원리금의 합계가 매기 동일하다.","w":"원리금의 합계가 매기 같은 방식은 원리금균등분할상환이다. 원금균등분할상환은 원금이 일정하고 이자가 줄어 원리금이 매기 감소한다.","c":"상"},"감정평2020_31-104-3":{"f":"다른 조건이 일정하다면, 대출채권의 듀레이션(평균 회수기간)은 원리금균등분할상환(CPM) 방식이 원금균등분할상환(CAM) 방식보다 길다.","w":"원금균등은 초기에 원금을 많이 회수하므로 평균 회수기간이 짧다. 원리금균등은 이보다 길다.","c":"상"},"감정평2020_31-104-4":{"f":"체증분할상환(GPM) 방식은 장래 소득이 늘어날 것으로 예상되는 차입자에게 적합한 대출방식이다.","w":"체증분할상환은 초기 상환액이 적고 뒤로 갈수록 늘어나므로 장래 소득 증가가 예상되는 차입자에게 맞다.","c":"상"},"감정평2020_31-104-5":{"f":"거치식(Interest-only Mortgage) 방식은 대출자 입장에서 금리수입이 늘어나는 상환 방식으로, 주택 저당대출보다 상업용 부동산 저당대출에서 주로 활용된다.","w":"거치식은 원금을 갚지 않아 잔액이 유지되므로 대출자의 이자수입이 줄지 않고, 상업용 부동산 대출에서 주로 쓴다.","c":"중"},"감정평2021_32-100-2":{"f":"가치상승공유형대출(SAM: Shared Appreciation Mortgage)은 담보물의 가치상승 일부분을 차입자가 사전약정에 의해 대출자에게 이전하기로 하는 조건의 대출이다.","w":"SAM은 낮은 이자를 받는 대신 담보물 가치상승분의 일부를 대출자가 가져가는 대출이다. 이전 방향이 반대로 적혔다.","c":"상"},"감정평2021_32-100-3":{"f":"기업의 구조조정을 촉진하기 위하여 기업구조조정 부동산투자회사에 대하여는 자산구성 제한 등 일부 규정을 적용하지 않지만, 최저자본금 규정은 적용된다.","w":"기업구조조정 리츠에는 자산구성 제한(제25조 제1항) 등 일부만 적용을 제외한다(부동산투자회사법 제49조의2 제3항). 최저자본금 규정은 그대로 적용된다.","c":"상"},"감정평2021_32-100-4":{"f":"부채금융은 대출이나 회사채 발행 등을 통해 타인자본을 조달하는 방법으로서 저당담보부증권(MBS) 등이 있고, 조인트벤처(joint venture)는 지분금융이다.","w":"조인트벤처는 공동 출자하는 지분금융이다. 부채금융은 대출·회사채처럼 타인자본을 빌리는 방식이다.","c":"중"},"감정평2021_32-100-5":{"f":"우리나라의 공적보증형태 역모기지제도로 현재 주택연금, 농지연금이 시행되고 있다.","w":"공적보증 역모기지는 주택연금과 농지연금이다. 산지연금은 없다.","c":"중"},"감정평2021_32-104-2":{"f":"저당대출차입자에게 주어진 조기상환권은 콜옵션(call option)의 일종으로, 차입자가 조기상환을 한다는 것은 대출잔액을 행사가격으로 하여 대출채권을 매입하는 것과 같다.","w":"차입자의 조기상환권은 콜옵션이다. 대출잔액을 내고 채권을 사들이는 것이므로 매각이 아니라 매입이다.","c":"상"},"감정평2022_33-97-3":{"f":"대출조건이 동일하다면 대출기간동안 차입자의 총원리금상환액은 원리금균등분할상환방식이 원금균등분할상환방식보다 크다.","w":"원리금균등은 원금 상환이 늦어 이자가 더 쌓이므로 총상환액이 원금균등보다 크다.","c":"상"},"감정평2022_33-101-5":{"f":"총부채원리금상환비율(DSR)은 소득기준으로, 담보인정비율(LTV)은 담보가치 기준으로 채무불이행위험을 측정하는 지표이다.","w":"DSR은 소득 대비 원리금 부담을 보고, LTV는 담보가치 대비 대출액을 본다. LTV는 소득기준 지표가 아니다.","c":"상"},"감정평2023_34-101-4":{"f":"점증상환방식은 초기에 대출이자의 일부만 내고, 나머지 이자는 원금에 가산하므로 부의 상환(negative amortization)이 일어날 수 있다.","w":"점증상환은 초기 상환액이 이자보다 적어 잔액이 늘어나는 부의 상환이 생길 수 있다. 이자를 전부 낸다면 부의 상환이 생기지 않는다.","c":"상"},"감정평2023_34-103-2":{"f":"부동산의 특성과 관련하여 고가성과 생산의 장기성으로 인해 부동산금융은 부동산의 거래나 개발 등에서 중요한 역할을 하게 된다.","w":"부동산은 거래금액이 크고 개발에 오랜 기간이 걸려 큰 자금이 필요하므로 금융의 역할이 커진다. 분할거래가 쉽다면 금융 필요성이 줄어든다.","c":"중"},"감정평2024_35-110-1":{"f":"콜옵션(call option)은 저당대출 차입자에게 주어진 조기상환권이다.","w":"조기상환권은 차입자가 갖는 콜옵션이다. 대출자에게 주어진 권리가 아니다.","c":"상"},"감정평2024_35-110-2":{"f":"금융기관은 위험을 줄이기 위해 부채감당률이 1보다 큰 대출안의 큰 순서대로 대출을 실행한다.","w":"부채감당률이 1보다 작으면 순영업소득으로 원리금을 못 갚는다. 1보다 큰 안 가운데 높은 순으로 대출한다.","c":"상"},"감정평2024_35-110-3":{"f":"대출수수료와 조기상환수수료를 차입자가 부담하는 경우, 차입자의 실효이자율은 조기상환시점이 앞당겨 질수록 상승한다.","w":"수수료를 짧은 기간에 나누어 부담하므로 상환 시점이 빠를수록 실효이자율은 높아진다.","c":"상"},"감정평2024_35-110-5":{"f":"고정금리방식의 대출에서 총상환액은 원리금균등분할상환방식이 원금균등분할상환방식보다 더 크다.","w":"같은 조건에서 원금균등이 원금을 먼저 갚아 총이자가 적고, 원리금균등의 총상환액이 더 크다.","c":"상"},"감정평2025_36-99-5":{"f":"랩어라운드(wrap-around)대출은 기존대출을 상환하지 않고 신규대출을 별도로 제공하는 방식이다.","w":"랩어라운드대출은 기존 대출을 유지한 채 그 위에 신규 대출을 포개 제공한다. 기존 대출을 상환한다는 말은 틀리다.","c":"상"},"감정평2025_36-100-1":{"f":"대출조건이 동일할 경우, 대출채권의 듀레이션(duration)은 원금균등분할상환, 원리금균등분할상환, 점증상환, 만기일시상환의 순으로 짧다.","w":"원금을 빨리 갚는 순서대로 듀레이션이 짧아져 원금균등, 원리금균등, 점증, 만기일시 순이다.","c":"상"},"감정평2026_37-109-1":{"f":"가입자가 오래 생존하는 장수명(長壽命)위험과 가입 이후 담보주택의 가격이 하락하는 가격위험은 모두 공사가 부담한다.","w":"주택연금은 비소구이므로 장수위험과 주택가격 하락위험을 한국주택금융공사가 부담한다. 가격위험은 가입자가 지지 않는다.","c":"중"},"감정평2026_37-109-2":{"f":"다른 조건이 동일한 경우 담보주택가격이 높을수록, 가입자의 나이가 많을수록 월지급금은 높아진다.","w":"나이가 많을수록 지급 기간이 짧아 월지급금이 커진다. 나이가 적으면 월지급금이 낮아진다.","c":"상"},"감정평2026_37-109-3":{"f":"다른 조건이 동일한 경우 주택연금 가입 후 담보주택의 가격이 상승하더라도 월지급금은 변하지 않는다.","w":"월지급금은 가입 시점의 주택가격과 나이로 정해져 가입 후 가격이 올라도 고정(정액형 기준)이다.","c":"중"},"감정평2026_37-109-4":{"f":"신청인의 보유주택수가 1주택이라면 주택가격과 상관없이 거주해야 가입이 가능하며, 2주택 이상인 경우 1주택 이외의 주택 처분을 조건으로 가입이 가능하다.","w":"가입 주택에 실제 거주해야 하는 요건이 빠졌다고 추정한다. 주택연금 요건은 개정이 잦아 현행 기준을 확인하지 못했다.","c":"하"},"감정평2017_28-112-2":{"f":"토지에 대한 종합부동산세는 종합합산과세대상인 경우에는 국내에 소재하는 해당 과세대상토지의 공시가격을 합한 금액이 5억원을 초과하는 자는 종합부동산세를 납부할 의무가 있다.","w":"종합합산 토지의 종합부동산세 공제금액은 5억원이다. 3억원이 아니다.","c":"상"},"감정평2017_28-114-3":{"f":"토지분 재산세의 과세대상 중 공장용지ㆍ전ㆍ답ㆍ과수원ㆍ목장용지와 같이 생산 활동에 이용되는 토지는 분리하여 과세한다.","w":"전·답·과수원·목장용지·공장용지 같은 생산 활동용 토지는 분리과세대상이다. 별도합산 대상이 아니다.","c":"중"},"감정평2018_29-103-1":{"f":"취득세는 비례세율을, 재산세는 비례세율과 누진세율을 함께 적용한다.","w":"취득세는 비례세율이고, 재산세는 토지·주택에 누진세율이 적용되는 구간이 있다. 둘 다 비례세율이라는 말은 틀리다.","c":"중"},"감정평2018_29-103-2":{"f":"상속세는 누진세율을, 등록면허세는 비례세율을 적용한다.","w":"상속세는 누진세율이고 등록면허세는 비례세율(정액세율 병행)이다. 둘 다 누진이라는 말은 틀리다.","c":"상"},"감정평2018_29-103-4":{"f":"종합부동산세와 재산세는 보유세에 속한다.","w":"보유세는 재산세와 종합부동산세이다. 증여세는 무상취득 시 내는 세금이다.","c":"상"},"감정평2018_29-103-5":{"f":"취득세와 재산세는 지방세에 속한다.","w":"취득세와 재산세는 지방세이다. 증여세는 국세이다.","c":"상"},"감정평2019_30-98-1":{"f":"종합부동산세와 재산세의 과세대상은 일치하지 않는다.","w":"재산세는 토지·건축물·주택 등을 모두 대상으로 하지만, 종합부동산세는 주택과 토지 중 일정 금액을 넘는 것만 대상으로 하고 건축물은 제외한다.","c":"상"},"감정평2021_32-111-5":{"f":"종합부동산세와 재산세의 과세기준일은 매년 6월 1일이다.","w":"두 세금의 과세기준일은 6월 1일이다. 6월 30일이 아니다.","c":"상"},"감정평2025_36-110-2":{"f":"재산세는 보유관련 조세로 지방세이다.","w":"재산세는 보유세이면서 지방세(시·군·구세)이다. 국세가 아니다.","c":"상"},"감정평2025_36-111-1":{"f":"조세부담의 전가여부에 따라 직접세와 간접세로 분류한다.","w":"조세부담을 다른 사람에게 넘길 수 있는지에 따라 간접세와 직접세로 나눈다. 보통세와 목적세는 용도 지정 여부에 따른 분류이다.","c":"상"},"감정평2025_36-111-2":{"f":"과세권자에 따라 국세와 지방세로 분류한다.","w":"과세권자가 국가인지 지방자치단체인지에 따라 국세와 지방세로 나눈다. 직접세·간접세는 조세부담 전가 여부에 따른 분류이다.","c":"상"},"감정평2025_36-111-4":{"f":"과세표준의 계산단위에 따라 종가세와 종량세로 분류한다.","w":"가액을 기준으로 하면 종가세, 수량·면적 등을 기준으로 하면 종량세이다. 독립세·부가세는 독립된 세원 유무에 따른 분류이다.","c":"상"},"감정평2025_36-111-5":{"f":"독립된 세원유무에 따라 독립세와 부가세로 분류한다.","w":"독립된 세원이 있으면 독립세, 다른 세금에 덧붙으면 부가세이다. 종가세·종량세는 과세표준 단위에 따른 분류이다.","c":"상"},"감정평2020_31-110-5":{"f":"3년 후에 주택자금 5억원을 만들기 위해 매 기간 납입해야 할 금액을 계산하는 경우, 감채기금계수를 사용한다.","w":"목표금액을 만들기 위한 매 기간 적립액은 감채기금계수(연금의 미래가치계수의 역수)를 곱해 구한다.","c":"상"},"감정평2021_32-99-2":{"f":"원리금균등분할상환방식에서 매 기간의 상환액을 계산할 경우 저당상수를 사용한다.","w":"저당상수는 원리금균등상환액을 구하는 계수이다. 원금균등은 원금을 기간 수로 나눈 값에 이자를 더해 계산한다.","c":"상"},"감정평2021_32-99-3":{"f":"기말에 일정 누적액을 만들기 위해 매 기간마다 적립해야 할 금액을 계산할 경우 감채기금계수를 사용한다.","w":"목표 누적액을 만드는 매기 적립액은 감채기금계수로 구한다. 연금의 현재가치계수는 일정 기간 연금의 현재 가치를 구할 때 쓴다.","c":"상"},"감정평2021_32-99-4":{"f":"연금의 미래가치계수에 일시불의 현재가치계수를 곱하면 연금의 현재가치계수가 된다.","w":"((1+r)^n-1)/r × 1/(1+r)^n = (1-(1+r)^-n)/r 이므로 연금의 현재가치계수가 된다. 일시불의 미래가치계수가 되지 않는다.","c":"상"},"감정평2021_32-99-5":{"f":"저당상수에 연금의 현재가치계수를 곱하면 1이 된다.","w":"저당상수는 연금의 현재가치계수의 역수이므로 둘을 곱하면 1이다. 일시불의 현재가치가 되지 않는다.","c":"상"},"감정평2023_34-99-5":{"f":"부동산 경기가 침체하는 시기에 상업용 부동산의 수익이 일정함에도 불구하고 부동산 가격이 떨어지는 것은 할인율이 높아지기 때문이다.","w":"수익이 같아도 할인율이 오르면 현재가치가 줄어 가격이 하락한다. 할인율이 낮아지면 가격은 오른다.","c":"상"},"감정평2017_28-104-1":{"f":"환원이율은 투하자본에 대한 수익비율로써 상각 전ㆍ세공제전의 이율을 말한다.","w":"환원이율의 정의에서 상각 전 기준을 상각 후로 바꿔 적은 것으로 추정한다. 교재마다 표현이 달라 확신하지 못했다.","c":"하"},"감정평2019_30-103-2":{"f":"감가상각 전의 순영업소득으로 가치를 추계하는 경우 감가상각률을 포함한 자본환원율을 사용해야 한다.","w":"상각 전 순영업소득에는 건물 감가분이 남아 있으므로 환원율에 상각률을 포함한다. 상각률을 제외하는 쪽은 상각 후 순영업소득이다.","c":"상"},"감정평2021_32-120-3":{"f":"직접환원법에서 사용할 환원율은 시장추출법으로 구하는 것을 원칙으로 한다. 다만, 시장추출법의 적용이 적절하지 않은 때에는 요소구성법, 투자결합법, 유효총수익승수에 의한 결정방법, 시장에서 발표된 환원율 등을 검토하여 조정할 수 있다.","w":"감정평가에 관한 규칙은 직접환원법의 환원율을 시장추출법으로 구하는 것을 원칙으로 한다. 요소구성법은 보조 방법이다.","c":"중"},"감정평2022_33-117-1":{"f":"운영경비에 감가상각비를 포함시킨 경우 상각후환원율을 적용한다.","w":"운영경비에 감가상각비를 넣으면 순영업소득이 상각 후 금액이므로 상각률을 뺀 환원율을 쓴다. 상각전환원율이 아니다.","c":"상"},"감정평2024_35-94-1":{"f":"직접환원법은 단일기간의 순수익을 적절한 환원율로 환원하여 대상물건의 가액을 산정하는 방법을 말한다.","w":"직접환원법은 한 기간의 순수익을 환원율로 나눈다. 복수기간의 순수익을 할인하는 것은 할인현금흐름분석법이다.","c":"상"},"감정평2024_35-94-2":{"f":"수익가액이란 수익환원법에 따라 산정된 가액을 말한다.","w":"수익가액은 수익환원법으로 산정한 가액이다. 수익분석법은 기업용 부동산 등에 쓰는 별개의 방법이다.","c":"상"},"감정평2024_35-94-3":{"f":"순수익은 대상물건에 귀속하는 적절한 수익으로서 유효총수익에서 운영경비를 공제하여 산정한다.","w":"순수익은 유효총수익에서 운영경비를 뺀 금액이다. 가능총수익에서 공제하는 것이 아니다.","c":"상"},"감정평2024_35-94-4":{"f":"직접환원법에서 사용할 환원율은 시장추출법으로 구하는 것을 원칙으로 한다.","w":"직접환원법의 환원율은 시장추출법을 원칙으로 하고, 투자결합법은 보조로 검토한다.","c":"중"},"감정평2016_27-118-2":{"f":"시설관리(Facility Management)는 시설사용자나 사용과 관련한 타부문의 요구에 단순히 부응하는 정도의 소극적이고 기술적인 측면을 중시하는 부동산관리를 의미한다.","w":"소극적·기술적 관리는 시설관리이다. 재산관리는 임대차관리와 수익 극대화를 다루는 보다 적극적인 관리이다.","c":"상"},"감정평2018_29-106-1":{"f":"자산관리(asset management)는 부동산시설의 자산 및 부채를 종합관리하는 것으로 시설사용자나 기업의 요구에 따르는 적극적인 관리에 해당한다.","w":"자산 및 부채를 종합관리하는 적극적 관리는 자산관리이다. 시설관리는 시설 유지에 치중하는 소극적 관리이다.","c":"중"},"감정평2018_29-106-3":{"f":"위탁관리방식은 자기관리방식에 비해 기밀유지가 불리한 측면이 있다.","w":"외부 업체에 맡기면 내부 정보가 밖으로 나갈 수 있어 기밀유지는 자기관리가 더 유리하다.","c":"상"},"감정평2018_29-106-4":{"f":"혼합관리방식은 자기관리방식에 비해 문제발생시 책임소재 파악이 어렵다.","w":"혼합관리는 자기관리와 위탁관리가 섞여 책임 구분이 불분명하다.","c":"상"},"감정평2018_29-106-5":{"f":"건물의 고층화와 대규모화가 진행되면서 자기관리방식에서 위탁관리방식으로 바뀌는 경향이 있다.","w":"건물이 커지고 복잡해질수록 전문업체에 맡기는 위탁관리가 늘어난다.","c":"상"},"감정평2019_30-112-5":{"f":"위탁관리방식은 관리 업무의 전문성과 효율성을 제고할 수 있으나 기밀유지에 불리한 단점이 있다.","w":"위탁관리는 전문성이 장점이지만 기밀유지는 자기관리보다 불리하다.","c":"상"},"감정평2020_31-99-5":{"f":"혼합관리방식에 있어 관리상의 문제가 발생할 경우, 책임소재에 대한 구분이 불명확하다.","w":"혼합관리는 관리 주체가 섞여 있어 책임소재가 불분명해질 수 있다.","c":"상"},"감정평2022_33-103-4":{"f":"재산관리(Property Management)란 부동산의 운영수익을 극대화하고 자산가치를 증진시키기 위한 임대차관리 등의 일상적인 건물운영 및 관리를 하는 것을 말한다.","w":"부동산 투자의 위험관리와 프로젝트 파이낸싱까지 하는 것은 자산관리이다. 재산관리는 임대차관리와 건물운영 중심이다.","c":"중"},"감정평2022_33-104-2":{"f":"혼합관리방식은 필요한 부분만 일부 위탁하는 방식으로 관리자들간의 협조가 원활하지 못할 수 있다.","w":"혼합관리는 관리자가 둘 이상이어서 협조가 어렵고 책임이 불분명할 수 있다. 협조가 긴밀하다고 단정할 수 없다.","c":"중"},"감정평2022_33-104-3":{"f":"위탁관리방식은 관리업무의 타성(惰性)을 방지할 수 있다.","w":"외부 전문업체가 맡으면 타성에 빠지기 어렵다. 타성은 자기관리방식의 단점이다.","c":"상"},"감정평2022_33-104-4":{"f":"위탁관리방식은 외부 전문가가 관리하므로 기밀 및 보안 유지에 불리하다.","w":"외부에 맡기면 기밀·보안 유지는 자기관리보다 불리하다.","c":"상"},"감정평2022_33-104-5":{"f":"혼합관리방식은 관리문제 발생시 책임소재가 불명확하다.","w":"혼합관리는 자기관리와 위탁관리가 섞여 책임소재가 불분명하다.","c":"상"},"감정평2024_35-117-5":{"f":"자기관리방식보다 기밀유지 측면에서 불리하다.","w":"위탁관리방식은 기밀유지에서 자기관리방식보다 불리하다.","c":"상"},"감정평2026_37-111-1":{"f":"자기관리는 관리의 전문성이 부족하고 임대료나 관리비의 객관적 산정이 어렵다.","w":"자기관리는 전문성이 부족하고 객관적 산정이 어렵다. 위탁관리는 전문업체의 기준으로 객관적 산정이 쉽다.","c":"중"},"감정평2016_27-102-5":{"f":"부채감당률(DCR)이 1보다 크면 순영업소득으로 원리금 지불능력이 충분하다.","w":"DCR은 순영업소득을 부채서비스액으로 나눈 값이다. 1보다 작으면 순영업소득으로 원리금을 다 갚지 못한다.","c":"상"},"감정평2017_28-89-1":{"f":"수익성지수법은 투자된 현금유입의 현재가치를 이 투자로부터 발생되는 현금유출의 현재가치로 나눈 것이다.","w":"수익성지수는 현금유입의 현재가치를 현금유출의 현재가치로 나눈 값이다. 분자·분모가 반대로 적혔다.","c":"상"},"감정평2018_29-93-1":{"f":"수익성지수는 투자개시시점에서의 현금유입의 현재가치와 현금지출의 현재가치 비율이다.","w":"수익성지수는 유입 현가를 유출 현가로 나눈 값이다. 순현가를 지출 현가로 나눈 값은 수익성지수에서 1을 뺀 값이다.","c":"상"},"감정평2019_30-92-5":{"f":"순현재가치가 0보다 큰 경우나 내부수익률이 요구수익률보다 큰 경우에는 투자한다.","w":"채택 기준은 순현재가치가 0보다 크거나 내부수익률이 요구수익률보다 큰 경우이다. 1은 수익성지수의 기준이다.","c":"상"},"감정평2020_31-108-1":{"f":"다른 조건이 일정하다면, 승수법에서는 승수가 작을수록 더 좋은 투자안이다.","w":"승수는 투자금을 회수하는 데 걸리는 기간이므로 작을수록 좋다.","c":"상"},"감정평2022_33-96-1":{"f":"투자규모가 상이한 투자안에서 수익성지수(PI)가 큰 투자안이 순현재가치(NPV)도 크다고 할 수 없다.","w":"PI는 비율이라 투자규모가 다르면 PI가 커도 NPV가 작을 수 있다.","c":"상"},"감정평2022_33-96-2":{"f":"서로 다른 투자안 A, B를 결합한 새로운 투자안의 내부수익률(IRR)은 A의 내부수익률과 B의 내부수익률을 합한 값이 아니다.","w":"내부수익률은 가법성이 없어 합산한 값이 아니다. 순현재가치는 가법성이 있다.","c":"상"},"감정평2022_33-96-3":{"f":"순현재가치법과 수익성지수법에서는 화폐의 시간가치를 고려한다.","w":"둘 다 현금흐름을 할인율로 현재가치화하므로 시간가치를 고려한다. 시간가치를 무시하는 것은 회수기간법, 회계적이익률법이다.","c":"상"},"감정평2022_33-96-4":{"f":"투자안마다 복수의 내부수익률이 대응될 수 있다.","w":"현금흐름의 부호가 여러 번 바뀌면 내부수익률이 둘 이상 나올 수 있다. 하나만 대응된다고 단정할 수 없다.","c":"상"},"감정평2024_35-114-4":{"f":"총투자수익률(ROI)은 순영업소득(NOI)을 총투자액으로 나눈 비율이다.","w":"총투자수익률은 순영업소득을 총투자액으로 나눈 값이다. 분자·분모가 반대로 적혔다.","c":"상"},"감정평2024_35-116-2":{"f":"서로 다른 내부수익률을 가지는 두 자산에 동시에 투자하는 투자안의 내부수익률은 각 자산의 내부수익률을 더한 것과 같지 않다.","w":"내부수익률은 가법성이 없어 단순히 더할 수 없다. 현금흐름을 합쳐 다시 구해야 한다.","c":"상"},"감정평2026_37-101-1":{"f":"투자자의 요구수익률이 12 %일 때, A의 순현재가치는 ‘0’이다.","w":"자료표 없이 선지 간 정합성으로 추정한 해설이다. 12%에서 순현재가치가 0이 되는 투자안은 B가 아니라고 보았다.","c":"하"},"감정평2026_37-101-2":{"f":"투자자의 요구수익률이 15 %일 때, 순현재가치는 B가 A보다 크다.","w":"자료표 없이 선지 간 정합성으로 추정했다. 12% 초과 15% 미만 구간에서 B가 A보다 크므로 15%에서도 같은 방향으로 본다.","c":"하"},"감정평2026_37-101-3":{"f":"투자자의 요구수익률이 8 %보다 클 때, 순현재가치는 A가 B보다 항상 크다고 할 수 없다.","w":"두 투자안의 순현재가치가 같아지는 수익률(교차점)을 경계로 우열이 바뀐다. 8% 초과 구간 전체에서 A가 크다는 말은 성립하지 않는다.","c":"하"},"감정평2026_37-101-5":{"f":"두 투자안의 순현재가치를 같게 하는 투자자의 요구수익률은 12 % 이하의 구간에 위치한다.","w":"자료표 없이 선지 간 정합성으로 추정했다. 12% 초과 15% 미만에서 B가 A보다 크다고 했으므로 두 순현재가치가 같아지는 수익률은 그 구간 밖에 있다.","c":"하"},"감정평2026_37-104-4":{"f":"다른 조건이 일정하다면 승수법에서는 승수가 작을수록 더 좋은 투자안이다.","w":"승수는 투자금을 회수하는 데 걸리는 기간 성격이라 작을수록 유리하다.","c":"상"},"감정평2016_27-105-4":{"f":"과수원을 감정평가할 때에 거래사례비교법을 원칙적으로 적용하여야 한다.","w":"감정평가에 관한 규칙은 과수원을 거래사례비교법으로 평가하도록 정한다. 수익환원법이 원칙이 아니다.","c":"상"},"감정평2017_28-105-5":{"f":"인근지역은 감정평가의 대상이 된 부동산이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다.","w":"대상부동산이 속한 지역이면서 지역요인을 공유하는 지역은 인근지역이다(감정평가에 관한 규칙 제2조 제13호). 유사지역은 대상부동산이 속하지 않는 지역이다.","c":"상"},"감정평2017_28-106-2":{"f":"부분평가란 일체로 이용되고 있는 물건의 일부만을 평가하는 것을 말한다.","w":"일체로 이용되는 물건의 일부만 평가하는 것은 부분평가이다. 조건부평가는 가치형성요인을 가정하거나 한정하는 조건을 붙여 평가하는 것이다.","c":"상"},"감정평2018_29-111-3":{"f":"유사지역이란 감정평가의 대상이 된 부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다.","w":"유사지역은 대상부동산이 속하지 않는 지역이다(감정평가에 관한 규칙 제2조 제14호). 속한 지역은 인근지역이다.","c":"상"},"감정평2019_30-104-3":{"f":"시산가액 조정시 공시지가기준법과 거래사례비교법은 서로 다른 감정평가방식으로 본다.","w":"시산가액을 비교할 때 공시지가기준법과 그 밖의 비교방식은 서로 다른 감정평가방식에 속한다고 본다(감정평가에 관한 규칙 제12조 제2항).","c":"상"},"감정평2020_31-85-2":{"f":"권리금을 개별로 감정평가하는 것이 곤란하거나 적절하지 아니한 경우에는 일괄하여 감정평가할 수 있으며, 이 경우 감정평가액은 유형재산가액과 무형재산가액으로 구분하여 표시하여야 한다.","w":"일괄평가한 권리금은 유형재산가액과 무형재산가액을 나누어 표시한다. 구분하지 않는다는 말이 틀리다.","c":"중"},"감정평2020_31-86-5":{"f":"수익환원법이란 대상물건이 장래 산출할 것으로 기대되는 순수익이나 미래의 현금흐름을 환원하거나 할인하여 대상물건의 가액을 산정하는 감정평가방법을 말한다.","w":"순수익이나 미래 현금흐름을 환원·할인해 가액을 구하는 방법은 수익환원법이다(감정평가에 관한 규칙 제2조 제10호). 수익분석법은 일반기업 경영으로 낸 총수익을 분석해 임대료를 구하는 방법이다.","c":"상"},"감정평2021_32-116-4":{"f":"감정평가의 목적에 비추어 사회통념상 필요하다고 인정되어 감정평가조건을 붙여 감정평가하는 경우에도 감정평가조건의 합리성, 적법성 및 실현가능성을 검토해야 한다.","w":"법령에 다른 규정이 있는 경우에만 검토를 생략할 수 있다. 사회통념상 필요해서 조건을 붙이는 경우는 생략하지 못한다(감정평가에 관한 규칙 제6조 제3항).","c":"상"},"감정평2022_33-119-2":{"f":"적정한 실거래가는 감정평가의 기준으로 적용하기에 적정하다고 판단되는 거래가격으로서, 거래시점이 도시지역은 3년 이내, 그 밖의 지역은 5년 이내인 거래가격을 말한다.","w":"도시지역은 3년 이내, 그 밖의 지역은 5년 이내이다(감정평가에 관한 규칙 제2조 제12호의2). 기간이 서로 바뀌어 적혔다.","c":"상"},"감정평2023_34-115-2":{"f":"시점수정은 사례물건의 임대료 변동률로 함을 원칙으로 한다.","w":"임대사례비교법의 시점수정은 대상물건이 아닌 임대사례 물건의 임대료 변동률로 한다.","c":"중"},"감정평2023_34-120-4":{"f":"감정평가법인등은 과수원을 감정평가할 때에 거래사례비교법을 적용해야 한다.","w":"과수원은 공시지가기준법이 아니라 거래사례비교법으로 평가한다. 토지에 해당하지 않고 별도로 정한 대상물건이다.","c":"중"},"감정평2024_35-91-4":{"f":"감정평가법인등이 토지를 감정평가할 때에는 공시지가기준법을 적용해야 한다.","w":"토지는 공시지가기준법으로 평가한다(감정평가에 관한 규칙 제14조 제1항). 수익환원법을 적용하는 것이 아니다.","c":"상"},"감정평2024_35-100-2":{"f":"주택으로 쓰는 층수가 3개 층으로 15세대가 거주할 수 있고 주택으로 쓰이는 바닥면적의 합계가 600제곱미터인 1개 동이며 구분소유가 아닌 건물의 감정평가는 토지와 건물을 개별로 감정평가하는 것을 원칙으로 한다.","w":"구분소유가 아닌 건물은 대상물건마다 개별로 평가하는 것이 원칙이다(감정평가에 관한 규칙 제7조 제1항). 일괄평가는 구분소유 건물이나 일체로 거래되는 경우에 한다.","c":"중"},"감정평2025_36-118-5":{"f":"시산가액 조정 시 공시지가기준법과 거래사례비교법은 서로 다른 감정평가방식으로 본다.","w":"공시지가기준법과 그 밖의 비교방식은 서로 다른 감정평가방식에 속한 것으로 본다(감정평가에 관한 규칙 제12조 제2항).","c":"상"},"감정평2025_36-120-1":{"f":"도시지역의 경우, 거래시점이 3년 이내의 것이어야 한다.","w":"도시지역은 3년 이내이다(감정평가에 관한 규칙 제2조 제12호의2). 4년이 아니다.","c":"상"},"감정평2025_36-120-2":{"f":"도시지역이 아닌 경우, 거래시점이 5년 이내의 것이어야 한다.","w":"도시지역 외 지역은 5년 이내이다(감정평가에 관한 규칙 제2조 제12호의2). 6년이 아니다.","c":"상"},"감정평2025_36-120-3":{"f":"적정한 실거래가의 기준이 되는 도시지역에 계획관리지역은 포함되지 않는다.","w":"도시지역은 국토계획법상 용도지역 중 도시지역을 말한다. 계획관리지역은 관리지역에 속하므로 포함되지 않는다.","c":"상"},"감정평2025_36-120-5":{"f":"실거래가는 인근지역 지가수준 등을 고려하여 적정하다고 판단되는 경우에 적정한 실거래가로 인정된다.","w":"신고된 거래가격 중 인근지역 지가수준 등을 고려해 감정평가법인등이 적정하다고 판단한 것만 적정한 실거래가이다(감정평가에 관한 규칙 제2조 제12호의2). 지가수준과의 차이와 무관하게 인정되지 않는다.","c":"상"},"감정평2026_37-117-2":{"f":"건물의 일부가 도시ㆍ군계획시설에 저촉되어 저촉되지 않은 잔여부분이 건물로서 효용가치가 없는 경우에는 그 잔여부분을 포함하여 감정평가하고, 잔여부분만으로도 독립건물로서의 가치가 있다고 인정되는 경우에는 그 잔여부분의 벽체나 기둥 등의 보수에 드는 비용 등을 고려하여 감정평가한다.","w":"잔여부분이 효용가치가 없으면 잔여부분까지 포함해 평가하고, 독립건물로 가치가 있으면 보수비를 고려해 저촉부분만 평가하는 것으로 기억한다. 실무기준 기준이라 규칙 조문은 붙이지 않는다.","c":"하"},"감정평2026_37-118-4":{"f":"광업권을 감정평가할 때에 광업재단의 감정평가액에서 해당 광산의 현존시설 가액을 빼고 감정평가해야 한다. 이 경우 광산의 현존시설 가액은 적정 생산규모와 가행조건 (稼行條件) 등을 고려하여 산정하되 과잉유휴시설을 포함하여 산정하지 않는다.","w":"현존시설 가액은 과잉유휴시설을 포함하지 않고 산정한다(감정평가에 관한 규칙 제23조 제1항).","c":"상"},"감정평2023_34-116-4":{"f":"거래사례는 위치에 있어서 동일성 내지 유사성이 있어야 하며, 인근지역에 소재하는 경우에는 지역요인비교를 필요로 하지 않는다.","w":"인근지역의 사례는 대상과 같은 지역이므로 지역요인 비교가 필요 없다. 유사지역이나 동일수급권의 사례에서 지역요인을 비교한다.","c":"상"},"감정평2026_37-119-2":{"f":"시점수정은 사례물건의 가격 변동률로 함이 원칙이다.","w":"거래사례비교법의 시점수정은 대상물건이 아닌 거래사례 물건의 가격 변동률로 한다.","c":"중"},"감정평2017_28-90-4":{"f":"장래 기대되는 수익의 흐름이 주어졌을 때, 요구수익률이 클수록 부동산의 가치는 감소한다.","w":"같은 수익을 더 높은 요구수익률로 할인하면 현재가치가 작아진다.","c":"상"},"감정평2018_29-94-2":{"f":"위험과 수익은 상충관계에 있으므로 효율적 투자선은 우상향하는 곡선이다.","w":"위험이 커질수록 기대수익도 커지므로 효율적 투자선은 우상향이다. 우하향하지 않는다.","c":"상"},"감정평2019_30-87-1":{"f":"총투자수익률에서 지분투자수익률을 차감하여 정(+)의 수익률이 나오는 경우에는 부(-)의 레버리지가 발생한다.","w":"총투자수익률이 지분투자수익률보다 크다는 것은 차입 때문에 지분수익률이 낮아졌다는 뜻이어서 부(-)의 레버리지이다.","c":"상"},"감정평2020_31-111-3":{"f":"투자자의 개별적인 위험혐오도에 따라 위험할증률이 결정된다.","w":"무위험률은 시장 전체의 이자율 수준으로 정해진다. 개별 투자자의 위험혐오도는 위험할증률에 반영된다.","c":"상"},"감정평2021_32-97-4":{"f":"무위험자산이 없는 경우의 최적 포트폴리오는 효율적 프런티어(efficient frontier)와 투자자의 무차별곡선이 접하는 점에서 결정되는데, 투자자가 위험선호형일 경우 최적 포트폴리오는 위험기피형에 비해 고위험-고수익 포트폴리오가 된다.","w":"위험선호형은 위험기피형보다 더 큰 위험을 감수하고 더 높은 수익을 택하므로 고위험-고수익 포트폴리오를 고른다.","c":"상"},"감정평2022_33-95-4":{"f":"두 개별자산으로 구성된 포트폴리오에서 자산간 상관계수가 음수인 경우에 양수인 경우보다 포트폴리오 위험절감효과가 높다.","w":"두 자산이 반대로 움직일수록(상관계수가 작을수록) 위험이 서로 상쇄되어 위험절감효과가 크다.","c":"상"},"감정평2023_34-96-1":{"f":"상업용 부동산투자는 일반적으로 다른 상품에 비하여 초기투자비용이 많이 들며 투자비용의 회수기간이 길고 경기침체에 민감하여 투자위험이 높다.","w":"상업용 부동산은 경기 변동에 민감해 투자위험이 높다. 경기침체에 민감하지 않다는 말이 틀리다.","c":"상"},"감정평2023_34-96-2":{"f":"시장위험이란 부동산시장의 수요·공급과 관련된 상황의 변화 때문에 발생하는 위험이다.","w":"입지여건의 변화 때문에 생기는 위험은 입지위험이다. 시장위험은 수요·공급 상황 변화에서 생긴다.","c":"상"},"감정평2023_34-96-4":{"f":"법·제도적 위험에는 소유권위험, 정부정책위험, 정치적위험, 불가항력적 위험이 있다.","w":"유동성위험은 법·제도적 위험이 아니라 금융위험(환금성) 쪽에 속한다.","c":"중"},"감정평2023_34-96-5":{"f":"위험과 수익간에는 정(+)의 관계가 성립한다.","w":"위험이 클수록 더 높은 수익을 요구하므로 둘은 정(+)의 관계이다.","c":"상"},"감정평2023_34-97-1":{"f":"부동산투자는 부동산이 갖고 있는 고유한 특성이 있어 환금성, 안전성 측면에서 주식 투자와 다르다.","w":"부동산은 거래가 오래 걸리고 가격이 커서 환금성과 안전성에서 주식과 다르다.","c":"상"},"감정평2023_34-97-2":{"f":"부동산은 실물자산이기 때문에 인플레이션 방어 능력이 우수하여 인플레이션 시기에 좋은 투자대상이다.","w":"실물자산은 물가가 오를 때 가치가 따라 올라 인플레이션 헤지가 된다. 디플레이션 시기에는 가격이 내려 불리하다.","c":"상"},"감정평2023_34-97-3":{"f":"부동산은 다른 투자상품에 비하여 거래비용의 부담이 크고 부동산시장은 정보의 비대칭성으로 인해 비효율적 시장이다.","w":"부동산시장은 정보의 비대칭성이 커서 비효율적 시장이다. 정보가 대칭이라는 설명이 틀리다.","c":"상"},"감정평2023_34-97-5":{"f":"투자의 금융성이란 투자자가 투자자산을 필요한 시기에 손실없이 현금으로 전환할 수 있는 환금성의 정도를 말한다.","w":"필요한 때 손실 없이 현금화할 수 있는 정도는 환금성(유동성)이다. 안전성은 원금 손실 위험이 작은 정도를 가리킨다.","c":"중"},"감정평2024_35-111-1":{"f":"다양한 자산들로 분산된 포트폴리오는 비체계적 위험을 감소시킨다.","w":"분산투자로 줄일 수 있는 것은 개별 자산 고유의 비체계적 위험이다. 체계적 위험은 분산해도 남는다.","c":"상"},"감정평2025_36-97-1":{"f":"기대수익률은 본질적으로 사전수익률을 의미한다.","w":"기대수익률은 투자 전에 예상하는 수익률이다. 투자 후 실제로 얻은 수익률은 실현수익률(사후수익률)이다.","c":"상"},"감정평2025_36-97-3":{"f":"기대수익률이 요구수익률보다 높으면, 대상부동산의 수요가 증가하여 기대수익률이 하락한다.","w":"수요가 늘면 가격이 올라 기대수익률이 내려가 요구수익률에 수렴한다. 요구수익률이 하락하는 것이 아니다.","c":"상"},"감정평2025_36-97-4":{"f":"명목이자율로서 무위험이자율은 실질이자율에 물가상승률을 더한 값이다.","w":"명목이자율은 실질이자율에 예상 물가상승률을 더한 값이다. 차감하지 않는다.","c":"상"},"감정평2025_36-97-5":{"f":"내부수익률이 요구수익률보다 큰 경우나 순현재가치가 0보다 큰 경우에는 투자한다.","w":"순현재가치의 채택 기준은 0보다 큰 것이다. 1은 수익성지수의 기준이다.","c":"상"},"감정평2016_27-115-5":{"f":"주택법령상 사업주체가 일반인에게 공급하는 공동주택 중 공공택지에서 공급하는 도시형 생활주택은 분양가상한제를 적용하지 않는다.","w":"주택법은 분양가상한제 적용 대상에서 도시형 생활주택을 제외한다. 현행 조문과 대조하지는 못했다.","c":"하"},"감정평2022_33-92-2":{"f":"저소득층에 대한 임대주택 공급은 소득의 간접분배효과가 있다.","w":"임대주택 공급은 현금이 아닌 주거서비스(현물)를 제공하는 방식이므로 소득의 간접분배효과를 낸다고 추정한다.","c":"하"},"감정평2026_37-96-2":{"f":"양질의 주택 건설을 촉진하고, 임대주택 공급을 확대할 것","w":"주거기본법 제3조는 양질의 주택 건설 촉진과 함께 임대주택 공급 확대를 주거정책 기본원칙으로 정한다. 국민주택이 아니라 임대주택이다.","c":"상"},"감정평2016_27-119-4":{"f":"동심원이론에서 점이지대는 중심업무지구와 저소득지대 사이에 위치하고 있다.","w":"점이지대는 중심업무지구와 저소득(노동자)주거지대 사이에 있다. 통근자지대는 가장 바깥쪽이다. 동심원이론이 다핵심·선형이론의 한계를 극복했다는 앞부분도 순서가 반대이다.","c":"중"},"감정평2018_29-87-1":{"f":"","w":"집적화 이익이 누적적 인과 과정으로 낙후된 지역까지 파급된다고 보는 것은 최소마찰비용이론이 아니다. 최소마찰비용이론은 입지 비용을 다루는 이론이다. 어느 이론을 가리키는지 확신하지 못했다.","c":"하"},"감정평2021_32-86-3":{"f":"동심원이론에서의 점이지대는 중심업무지구에 직장 및 생활터전이 있어 중심업무지구에 근접하여 거주하는 지대를 말한다.","w":"중심업무지구에 인접한 점이지대의 설명은 동심원이론에 속한다. 선형이론은 교통축을 따라 도시가 확장된다고 본다.","c":"중"},"감정평2026_37-94-4":{"f":"탈도시화(disurbanization)는 도시의 인구가 도시 밖으로 벗어나 감소하는 현상을 말한다.","w":"도시 인구가 도시 밖으로 빠져나가 줄어드는 현상은 탈도시화이다. 가도시화는 이와 다른 개념이다.","c":"중"},"감정평2017_28-113-1":{"f":"소매점포 개설을 위한 시장분석의 절차는 시장선택 → 구역분석 → 부지평가의 3단계로 이루어진다.","w":"시장을 고르고, 상권 구역을 분석한 뒤, 개별 부지를 평가하는 순서이다. 부지평가가 먼저 오지 않는다.","c":"중"},"감정평2022_33-88-3":{"f":"뢰쉬(A. Lösch)의 최대수요이론에서는 입지분석에 있어 대상지역 내 원자재가 어디에나 있다는 전제 하에, 수요가 최대가 되는 지점이 최적입지라고 본다.","w":"뢰쉬는 원자재가 어디서나 구할 수 있다고 보고 수요가 최대인 지점을 최적입지로 삼았다. 원자재의 불균등 분포는 베버의 전제이다.","c":"상"},"감정평2017_28-103-2":{"f":"감가수정의 방법은 직접법과 간접법이 있으며, 직접법에는 내용년수법, 관찰감가법 및 분해법이 있다. 감가수정액의 산정은 이 세가지 방법을 병용하여 산정할 수 있다.","w":"세 방법 가운데 하나를 쓰거나 병용할 수 있다. 반드시 병용해야 하는 것은 아니다.","c":"중"},"감정평2017_28-103-3":{"f":"감가수정은 재조달원가에서 부동산가격에 영향을 미치는 물리적ㆍ기능적ㆍ경제적 감가요인 등을 고려하고, 그에 해당하는 감가수정액을 공제하여, 기준시점 현재 대상물건의 가격을 적정화하기 위한 것이다.","w":"감가수정은 기준시점의 대상물건 가액을 적정화하는 작업이다(감정평가에 관한 규칙 제2조 제12호). 기간손익의 배분은 회계상 감가상각의 목적이다.","c":"상"},"감정평2017_28-103-4":{"f":"감정평가대상이 되는 부동산의 상태를 면밀히 관찰한 후 감정평가사의 폭넓은 경험과 지식에 의존하는 것이 관찰감가법이다.","w":"상태를 관찰해 평가사의 경험과 지식으로 감가액을 정하는 방법은 관찰감가법이다. 분해법은 감가요인별로 나누어 산정한다.","c":"상"},"감정평2017_28-103-5":{"f":"감가요인을 물리적ㆍ기능적ㆍ경제적 요인으로 세분하고, 치유가능ㆍ불능항목으로 세분하여 각각의 발생감가의 합계액을 감가수정액으로 하는 방법이 분해법이다.","w":"요인별·치유 가능 여부별로 나누어 감가를 합산하는 방법은 분해법이다. 관찰감가법은 상태를 보고 평가사가 판단한다.","c":"상"},"감정평2022_33-115-2":{"f":"적산법에 의한 임대료 평가에서는 대상물건의 기초가액에 기대이율을 곱하여 산정된 기대수익에 대상물건을 계속하여 임대하는 데에 필요한 경비를 더한다.","w":"적산법은 기초가액에 기대이율을 곱한다(감정평가에 관한 규칙 제2조 제6호). 재조달원가가 아니다.","c":"상"},"감정평2023_34-117-1":{"f":"","w":"원가방식과 밀접한 원칙의 구성이 틀렸다고 보이나 어느 원칙이 잘못 들어갔는지 근거를 확인하지 못했다.","c":"하"},"감정평2023_34-117-3":{"f":"대치원가(replacement cost)란 건축자재, 설비공법 등에 있어 기준시점의 표준적인 것을 사용한 적정원가로서 이미 기능적 감가는 반영되어 있다.","w":"재조달원가는 기준시점을 기준으로 구하므로 신축시점이 아니라 기준시점의 표준적인 자재·공법을 쓴다.","c":"중"},"감정평2023_34-117-4":{"f":"재조달원가를 구하는 방법은 직접법으로 총가격산법(총량조사법), 부분별단가적용법, 단위비교법 등이 있고, 간접법으로 변동율적용법(비용지수법) 등이 있다.","w":"변동률적용법(비용지수법)은 직접 조사하지 않고 지수로 구하는 간접법이다. 부분별단가적용법과 단위비교법은 직접법에 들어간다.","c":"중"},"감정평2023_34-117-5":{"f":"감정평가에 있어서 감가요인은 물리적요인, 기능적요인, 경제적요인이 있으며, 감가상각에 있어서 감가요인은 물리적요인, 기능적요인이다.","w":"회계상 감가상각은 물리적·기능적 요인만 보고 경제적 요인은 제외한다는 구분이 일반적이다.","c":"중"},"감정평2017_28-102-4":{"f":"균형의 원칙이란 부동산의 유용성이 최고도로 발휘되기 위해서는 부동산구성요소의 결합에 균형이 있어야 한다는 것을 말한다.","w":"구성요소 결합의 균형은 균형의 원칙이다. 적합의 원칙은 외부환경과의 어울림이다.","c":"상"},"감정평2019_30-99-1":{"f":"지역분석은 일반적으로 개별분석에 선행하여 행하는 것으로 그 지역 내의 표준적 이용과 가격수준을 판정하는 것이다.","w":"지역분석은 지역의 표준적 이용과 가격수준을 판정한다. 최유효이용을 판정하는 것은 개별분석이다.","c":"상"},"감정평2019_30-99-2":{"f":"인근지역이란 대상부동산이 속한 지역으로 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역이다.","w":"인근지역이 공유하는 것은 개별요인이 아니라 지역요인이다(감정평가에 관한 규칙 제2조 제13호).","c":"상"},"감정평2019_30-99-4":{"f":"개별분석이란 지역분석의 결과로 얻어진 정보를 기준으로 대상부동산의 가격을 구체화ㆍ개별화시키는 작업을 말한다.","w":"개별분석은 지역분석 결과를 바탕으로 대상부동산의 최유효이용과 구체적 가격을 판정한다. 표준화·일반화는 지역분석 쪽의 성격이다.","c":"중"},"감정평2019_30-99-5":{"f":"지역분석 시에는 적합의 원칙에, 개별분석 시에는 균형의 원칙에 더 유의하여야 한다.","w":"지역분석은 외부환경과의 어울림인 적합의 원칙에, 개별분석은 구성요소 결합의 균형의 원칙에 중점을 둔다.","c":"상"},"감정평2019_30-102-1":{"f":"토지이용흡수율 분석은 경제적 타당성 여부판단에 활용된다.","w":"흡수율 분석은 개발 시장성과 사업 수익성을 판단하는 데 쓰인다.","c":"중"},"감정평2021_32-114-3":{"f":"인근지역이란 대상부동산이 속한 지역으로서 부동산의 이용이 동질적이고 가치형성요인 중 지역요인을 공유하는 지역을 말한다.","w":"인근지역은 개별요인이 아니라 지역요인을 공유하는 지역이다(감정평가에 관한 규칙 제2조 제13호).","c":"상"},"감정평2021_32-115-3":{"f":"적합의 원칙이란 부동산의 유용성이 최고도로 발휘되기 위해서는 부동산이 외부환경과 적합해야 한다는 것을 말한다.","w":"외부환경과 어울려야 한다는 원칙은 적합의 원칙이다. 균형의 원칙은 내부 구성요소의 균형이다.","c":"상"},"감정평2024_35-95-4":{"f":"부동산의 가격이 내부적인 요인에 의하여 긍정적 또는 부정적 영향을 받아 형성되는 것은 균형의 원칙에 해당된다.","w":"내부 요인의 균형에 따른 가격 형성은 균형의 원칙이다. 외부 요인은 적합의 원칙이다.","c":"상"},"감정평2024_35-97-2":{"f":"유사지역이란 대상부동산이 속하지 아니하는 지역으로서 인근지역과 유사한 특성을 갖는 지역을 말한다.","w":"유사지역은 대상부동산이 속하지 않는 지역이다(감정평가에 관한 규칙 제2조 제14호).","c":"상"},"감정평2024_35-97-3":{"f":"동일수급권이란 대상부동산과 수요ㆍ공급 관계가 성립하고 가치 형성에 서로 영향을 미치는 관계에 있는 다른 부동산이 존재하는 권역을 말한다.","w":"동일수급권은 가치 형성에 서로 영향을 미치는 부동산이 있는 권역이다(감정평가에 관한 규칙 제2조 제15호). 영향을 미치지 않는다는 말이 틀리다.","c":"상"},"감정평2024_35-97-4":{"f":"지역분석은 대상지역 내 토지의 표준적 이용 및 가격수준을 판정하는 것이다.","w":"지역분석은 지역의 표준적 이용과 가격수준을 판정한다. 최유효이용과 대상부동산의 가격은 개별분석에서 판정한다.","c":"상"},"감정평2024_35-97-5":{"f":"지역분석은 개별분석 이전에 실시하는 것이 일반적이다.","w":"지역분석은 개별분석에 선행한다.","c":"상"},"감정평2017_28-108-1":{"f":"부동산시장은 부동산 재화와 서비스가 교환되는 매커니즘이기 때문에 유형의 부동산 거래는 물론 무형의 이용과 관련한 권리도 포함된다.","w":"부동산시장은 유형의 부동산뿐 아니라 임대차·이용권 같은 무형의 권리 거래도 포함한다.","c":"상"},"감정평2017_28-108-2":{"f":"일반적으로 부동산시장은 일반시장에 비해 거래비용이 많이 들고, 수요자와 공급자의 시장진출입이 제약을 받게 되어 불완전경쟁시장이 된다.","w":"거래비용이 크고 진출입이 제약되면 불완전경쟁시장이 된다. 완전경쟁시장은 이런 제약이 없는 시장이다.","c":"상"},"감정평2017_28-108-4":{"f":"정부가 제품의 품질이나 규격을 통제하는 건축기준은 질적규제의 예로 들 수 있다.","w":"품질·규격을 통제하는 규제는 질적규제이다. 양적규제는 공급량·가격·용적률처럼 수량을 제한하는 규제이다.","c":"중"},"감정평2017_28-108-5":{"f":"강성 효율적 시장은 공표된 것이건 그렇지 않은 것이건 어떠한 정보도 이미 가치에 반영되어 있는 시장이다.","w":"공표되지 않은 정보까지 반영하는 시장은 강성 효율적 시장이다. 준강성은 공표된 정보만 반영한다.","c":"상"},"감정평2018_29-86-4":{"f":"부동산시장은 주식시장이나 일반상품시장보다 더 불완전하고 비효율적이지만 할당 효율적일 수 있다.","w":"불완전경쟁시장이어도 할당(배분) 효율적일 수 있다. 완전경쟁만 할당 효율적인 것은 아니다.","c":"중"},"감정평2019_30-107-2":{"f":"부동산의 공급이 탄력적일수록 수요증가에 따른 가격변동의 폭이 작다.","w":"공급이 탄력적이면 수요가 늘 때 공급량이 쉽게 늘어 가격은 덜 오른다.","c":"상"},"감정평2021_32-88-1":{"f":"일반상품의 시장과 달리 조직성이 없고 지역을 한정하는 특성이 있다.","w":"부동산시장은 일반상품시장과 달리 조직화되어 있지 않고 지역별로 나뉜다(지역성).","c":"상"},"감정평2021_32-88-2":{"f":"토지의 자연적 특성인 지리적 위치의 고정성으로 인하여 개별화된다.","w":"지리적 위치의 고정성(부동성)은 인문적 특성이 아니라 자연적 특성이다.","c":"상"},"감정평2021_32-88-3":{"f":"매매의 장기성으로 인하여 유동성과 환금성이 낮다.","w":"부동산은 매매에 시간이 오래 걸리므로 유동성과 환금성이 낮다.","c":"상"},"감정평2021_32-88-4":{"f":"거래정보의 비대칭성으로 인하여 정보수집이 어렵고 은밀성이 확대된다.","w":"부동산은 개별성 때문에 정보가 비대칭이어서 정보수집이 어렵고 거래의 은밀성이 커진다.","c":"상"},"감정평2022_33-89-2":{"f":"강성 효율적 시장은 정보가 완전하고 모든 정보가 공개되어 있으며 정보비용이 없다는 완전경쟁시장의 조건을 만족한다.","w":"정보가 완전하고 정보비용이 없는 완전경쟁시장의 조건에 부합하는 것은 강성 효율적 시장이다. 약형은 과거 정보만 반영한다.","c":"중"},"감정평2022_33-89-3":{"f":"부동산시장은 주식시장이나 일반적인 재화시장보다 더 불완전경쟁적이지만 배분 효율성을 달성할 수 있다.","w":"불완전경쟁시장이어도 배분(할당) 효율성은 가능하다. 달성할 수 없다는 말이 틀리다.","c":"중"},"감정평2022_33-89-4":{"f":"강성 효율적 시장에서는 정보를 이용하여 초과이윤을 얻을 수 없다.","w":"강성 효율적 시장은 공표·미공표 정보를 모두 반영하므로 어떤 정보로도 초과이윤을 얻지 못한다.","c":"상"},"감정평2022_33-89-5":{"f":"준강성 효율적 시장의 개념은 약성 효율적 시장의 성격을 모두 포함하고 있다.","w":"효율성의 강도는 약성, 준강성, 강성 순으로 커진다. 준강성은 약성의 성격을 포함한다.","c":"상"},"감정평2023_34-90-1":{"f":"할당 효율적 시장은 완전경쟁시장을 의미하지 않으며 불완전경쟁시장도 할당 효율적 시장이 될 수 있다.","w":"완전경쟁이 아니어도 자원이 효율적으로 배분되면 할당 효율적 시장이 될 수 있다.","c":"중"},"감정평2023_34-90-3":{"f":"약성 효율적 시장에서 과거의 역사적 정보를 통해 정상 이상의 수익을 획득할 수 없다.","w":"약성 효율적 시장에서는 과거 정보가 이미 가격에 반영되어 있어 그 정보로 초과수익을 얻을 수 없다.","c":"상"},"감정평2023_34-90-4":{"f":"완전경쟁시장에서는 초과이윤이 발생하지 않는다.","w":"완전경쟁시장에서는 자유로운 진입과 이탈로 장기적으로 초과이윤이 사라진다.","c":"상"},"감정평2023_34-90-5":{"f":"준강성 효율적 시장에서 공표된 정보가 시장가치에 반영된다.","w":"준강성은 공표된 정보만 반영한다. 공표되지 않은 정보까지 반영하는 시장은 강성이다.","c":"상"},"감정평2026_37-93-1":{"f":"효율적 할당(efficient allocation)이란 위험을 감안한 모든 투자대안의 수익률이 동일하도록 자원이 할당되는 것을 말한다.","w":"효율적 할당은 위험을 고려한 후의 투자수익률이 모든 대안에서 같아지는 상태이다. 위험과 무관하게 같다는 말이 틀리다.","c":"중"},"감정평2026_37-93-3":{"f":"약성 효율적 시장은 과거의 정보를 지체없이 시장가치에 반영하는 시장이므로 기술적 분석을 통해 초과이윤을 획득할 수 없다.","w":"공표된 모든 정보를 반영하는 것은 준강성 효율적 시장이다. 약성은 과거 정보만 반영하므로 기술적 분석이 소용없다.","c":"상"},"감정평2026_37-93-4":{"f":"약성ㆍ준강성ㆍ강성 효율적 시장 모두 정보비용이 존재하는 것은 아니다.","w":"정보비용 유무를 어느 시장에 붙이느냐에 따라 틀리는 문장으로 보이나, 교재별 설명이 달라 확신하지 못했다.","c":"하"},"감정평2026_37-93-5":{"f":"불완전경쟁시장도 할당 효율적 시장이 될 수 있다.","w":"불완전경쟁시장이어도 자원이 효율적으로 배분되면 할당 효율적 시장이 될 수 있다.","c":"중"},"감정평2026_37-95-4":{"f":"부동산은 대체가능성이 낮은 재화이기에 부동산시장에서는 공매(short selling)가 어렵다.","w":"부동산은 개별성이 강하고 대체가 어려워 빌려서 파는 공매가 사실상 이루어지기 어렵다.","c":"중"},"감정평2021_32-84-5":{"f":"수요의 가격탄력성이 비탄력적이면 가격의 변화율보다 수요량의 변화율이 더 작다.","w":"비탄력적이면 가격이 변해도 수요량은 덜 변한다.","c":"상"},"감정평2023_34-88-5":{"f":"수요가 증가하는 경우, 공급의 가격탄력성이 작을수록 균형가격의 상승폭은 크고 균형량의 증가폭은 작다.","w":"공급이 비탄력적이면 수요 증가에 공급량이 따라가지 못해 가격이 크게 오르고 거래량은 조금 는다.","c":"상"},"감정평2023_34-91-5":{"f":"제품의 가격이 가계소득에서 차지하는 비중이 작을수록 수요의 탄력성이 더 비탄력적이다.","w":"가계소득에서 차지하는 비중이 작은 재화는 가격이 변해도 수요량이 덜 변하므로 비탄력적이다.","c":"상"},"감정평2018_29-90-5":{"f":"부동산가치는 부동산의 소유에서 비롯되는 미래의 편익을 현재가치로 환원한 값이다.","w":"가치는 미래 편익을 현재가치로 환산한 값이다. 현재 편익을 미래가치로 환원하는 것이 아니다.","c":"상"},"감정평2019_30-100-4":{"f":"시장가치란 대상물건이 통상적인 시장에서 충분한 기간 동안 거래를 위하여 공개된 후 그 대상물건의 내용에 정통한 당사자 사이에 신중하고 자발적인 거래가 있을 경우 성립될 가능성이 가장 높다고 인정되는 가액을 말한다.","w":"시장가치는 매수인이 제시한 최고 가격이 아니다. 정통한 당사자 사이의 거래에서 성립될 가능성이 가장 높은 가액이다(감정평가에 관한 규칙 제2조 제1호).","c":"상"},"감정평2020_31-116-5":{"f":"이전성은 경제적인 측면이 아닌 법률적인 측면에서의 가치발생요인이다.","w":"가치발생요인 중 유효수요와 상대적 희소성은 경제적 측면이고, 이전성은 법률적 측면이다.","c":"상"},"감정평2018_29-113-1":{"f":"다가구주택은 개별주택가격의 공시대상이다.","w":"다가구주택은 단독주택으로 보아 개별주택가격 공시대상이다. 공동주택가격은 아파트·연립·다세대에 대해 공시한다.","c":"상"},"감정평2018_29-113-2":{"f":"개별공시지가의 공시기준일이 7월 1일인 경우도 있다.","w":"개별공시지가의 공시기준일은 원칙적으로 1월 1일이고, 1월 2일부터 6월 30일 사이에 분할·합병 등이 생긴 토지는 7월 1일이다. 6월 1일인 경우는 없다.","c":"중"},"감정평2018_29-113-3":{"f":"표준주택에 그 주택의 사용ㆍ수익을 제한하는 권리가 설정되어 있을 때에는 그 권리가 없는 것으로 보고 적정가격을 산정하여야 한다.","w":"표준주택 적정가격은 사용·수익 제한 권리가 없는 상태를 가정해 산정한다.","c":"상"},"감정평2018_29-113-5":{"f":"표준지공시지가의 공시권자는 국토교통부장관이다.","w":"표준지공시지가는 국토교통부장관이 공시하고, 개별공시지가는 시장·군수·구청장이 결정·공시한다.","c":"상"},"감정평2019_30-106-5":{"f":"상향여과는 저소득층 주거지역에서 주택의 개량을 통한 가치상승분이 주택개량비용보다 큰 경우에 발생한다.","w":"개량 가치상승분이 개량비용보다 크면 저소득층 주택이 개량되어 상향여과가 일어난다. 하향여과는 반대로 주택 수준이 낮아지는 과정이다.","c":"상"},"감정평2022_33-90-2":{"f":"상향여과는 저소득층 주거지역에서 주택의 개량을 통한 가치상승분이 주택개량비용보다 큰 경우에 발생한다.","w":"저소득층 지역에서 개량이 이득이면 주택 수준이 올라 상향여과가 생긴다. 고소득층 지역의 하향여과와 구분된다.","c":"상"},"감정평2022_33-90-3":{"f":"다른 조건이 동일할 경우 고가주택에 가까이 위치한 저가주택에는 정(+)의 외부효과가 발생한다.","w":"고가주택 가까이 있는 저가주택은 주변 환경 덕에 가치가 오르는 정(+)의 외부효과를 받는다.","c":"상"},"감정평2022_33-90-4":{"f":"민간주택시장에서 불량주택이 발생하는 것은 시장실패를 의미하는 것은 아니다.","w":"불량주택은 시장 기능의 결과로 나타나는 현상이라 시장실패로 단정하지 않는다. 시장실패와 연결해 공공 개입의 근거로 삼는 견해와 갈린다.","c":"하"},"감정평2022_33-90-5":{"f":"주거분리현상은 도시지역은 물론 도시와 지리적으로 인접한 근린지역에서도 발생한다.","w":"주거분리는 도시지역과 인접 근린지역 모두에서 나타난다. 도시지역에서만 발생한다는 말이 틀리다.","c":"상"},"감정평2025_36-91-2":{"f":"고소득층 주거지역에 인접한 저소득층 주거지역에서 주택개량을 통한 가치상승분이 주택개량비용보다 큰 경우, 상향여과과정이 발생한다.","w":"개량의 가치상승분이 비용보다 크면 개량이 이루어져 상향여과가 생긴다. 작으면 개량이 일어나지 않는다.","c":"상"},"감정평2019_30-119-4":{"f":"호이트(H. Hoyt)는 고급주택지가 고용기회가 많은 도심지역과의 교통이 편리한 지역에 선형으로 입지한다고 보았다.","w":"호이트의 선형이론에서는 고소득층의 고급주택지가 교통축을 따라 도심과 연결되며 선형으로 입지한다. 저급주택지가 아니다.","c":"중"}};
